1	/****************************************************************************
2	 * apps/examples/uvc_test/uvc_test.c
3	 *
4	 * Simple USB Camera (UVC) test program
5	 * Tests basic video capture functionality
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
