21	/****************************************************************************
22	 * Pre-processor Definitions
23	 ****************************************************************************/
24	
25	#define VIDEO_DEV_PATH    "/dev/video"
26	#define TEST_WIDTH        320
27	#define TEST_HEIGHT       240
28	#define TEST_BUF_COUNT    3
29	#define TEST_CAPTURE_NUM  5
30	#define TEST_SAVE_PATH    "/tmp/uvc_test"
31	
32	/****************************************************************************
33	 * Private Types
34	 ****************************************************************************/
