45	
46	static int save_frame_to_file(const uint8_t *data, uint32_t size, int index)
47	{
48	  char filename[64];
49	  int fd;
50	  ssize_t written;
51	
52	  snprintf(filename, sizeof(filename), "%s/frame_%04d.raw",
53	           TEST_SAVE_PATH, index);
54	
55	  fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0666);
56	  if (fd < 0)
57	    {
58	      printf("ERROR: Failed to create file %s: %d\n", filename, errno);
59	      return -errno;
60	    }
61	
62	  written = write(fd, data, size);
63	  close(fd);
64	
65	  if (written != size)
66	    {
67	      printf("ERROR: Failed to write frame data: %zd\n", written);
68	      return -EIO;
69	    }
70	
71	  printf("Saved frame %d to %s (%u bytes)\n", index, filename, size);
72	  return OK;
73	}
