79	int uvc_test_main(int argc, char *argv[])
80	{
81	  struct v4l2_format fmt;
82	  struct v4l2_requestbuffers req;
83	  struct v4l2_buffer buf;
84	  struct v_buffer *buffers;
85	  int fd;
86	  int ret;
87	  int i;
88	
89	  printf("=== USB Camera (UVC) Test Program ===\n");
90	
91	  /* Create save directory */
92	
93	  ret = mkdir(TEST_SAVE_PATH, 0777);
94	  if (ret < 0 && errno != EEXIST)
95	    {
96	      printf("ERROR: Failed to create directory %s: %d\n",
97	             TEST_SAVE_PATH, errno);
98	      return ERROR;
99	    }
100	
101	  /* Initialize video driver (creates /dev/video device) */
102	
103	  printf("Initializing video driver: %s\n", VIDEO_DEV_PATH);
104	  ret = capture_initialize(VIDEO_DEV_PATH);
105	  if (ret != 0)
106	    {
107	      printf("ERROR: Failed to initialize video: %d (errno=%d)\n", ret, errno);
108	      return ERROR;
109	    }
110	
111	  printf("Video driver initialized successfully\n");
112	
113	  /* Open video device */
114	
115	  printf("Opening video device: %s\n", VIDEO_DEV_PATH);
116	  fd = open(VIDEO_DEV_PATH, O_RDWR);
117	  if (fd < 0)
118	    {
119	      printf("ERROR: Failed to open %s: %d\n", VIDEO_DEV_PATH, errno);
120	      return ERROR;
121	    }
122	
123	  printf("Video device opened successfully (fd=%d)\n", fd);
124	
125	  /* Query capabilities */
126	
127	  struct v4l2_capability cap;
128	  ret = ioctl(fd, VIDIOC_QUERYCAP, (uintptr_t)&cap);
129	  if (ret < 0)
130	    {
131	      printf("ERROR: VIDIOC_QUERYCAP failed: %d\n", errno);
132	      goto err_close;
133	    }
134	
135	  printf("Device capabilities:\n");
136	  printf("  Driver: %s\n", cap.driver);
137	  printf("  Card: %s\n", cap.card);
138	  printf("  Bus: %s\n", cap.bus_info);
139	  printf("  Capabilities: 0x%08x\n", cap.capabilities);
140	
141	  /* Set format */
142	
143	  printf("Setting video format: %dx%d\n", TEST_WIDTH, TEST_HEIGHT);
144	  memset(&fmt, 0, sizeof(fmt));
145	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
146	  fmt.fmt.pix.width = TEST_WIDTH;
147	  fmt.fmt.pix.height = TEST_HEIGHT;
148	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
149	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
150	
151	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
152	  if (ret < 0)
153	    {
154	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
155	      goto err_close;
156	    }
157	
158	  printf("Format set successfully\n");
159	  printf("  Actual size: %dx%d\n", fmt.fmt.pix.width, fmt.fmt.pix.height);
160	  printf("  Bytes per line: %d\n", fmt.fmt.pix.bytesperline);
161	  printf("  Image size: %d\n", fmt.fmt.pix.sizeimage);
162	
163	  /* Compute buffer size if not reported by driver */
164	
165	  if (fmt.fmt.pix.sizeimage == 0)
166	    {
167	      fmt.fmt.pix.sizeimage = fmt.fmt.pix.width * fmt.fmt.pix.height * 2;
168	      printf("  Computed image size: %d (RGB565)\n", fmt.fmt.pix.sizeimage);
169	    }
170	
171	  /* Request buffers */
172	
173	  printf("Requesting %d buffers\n", TEST_BUF_COUNT);
174	  memset(&req, 0, sizeof(req));
175	  req.count = TEST_BUF_COUNT;
176	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
177	  req.memory = V4L2_MEMORY_USERPTR;
178	
179	  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
180	  if (ret < 0)
181	    {
182	      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
183	      goto err_close;
184	    }
185	
186	  printf("Buffers requested: %d\n", req.count);
187	
188	  /* Allocate and queue buffers */
189	
190	  buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
191	  if (buffers == NULL)
192	    {
193	      printf("ERROR: Failed to allocate buffer array\n");
194	      goto err_close;
195	    }
196	
197	  for (i = 0; i < req.count; i++)
198	    {
199	      buffers[i].length = fmt.fmt.pix.sizeimage;
200	      buffers[i].start = (uint8_t *)memalign(32, buffers[i].length);
201	      if (buffers[i].start == NULL)
202	        {
203	          printf("ERROR: Failed to allocate buffer %d\n", i);
204	          goto err_free_buffers;
205	        }
206	
207	      memset(&buf, 0, sizeof(buf));
208	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
209	      buf.memory = V4L2_MEMORY_USERPTR;
210	      buf.index = i;
211	      buf.m.userptr = (uintptr_t)buffers[i].start;
212	      buf.length = buffers[i].length;
213	
214	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
215	      if (ret < 0)
216	        {
217	          printf("ERROR: VIDIOC_QBUF failed for buffer %d: %d\n", i, errno);
218	          goto err_free_buffers;
219	        }
220	
221	      printf("Buffer %d queued (addr=%p, size=%u)\n",
222	             i, buffers[i].start, buffers[i].length);
223	    }
224	
225	  /* Start streaming */
226	
227	  printf("Starting video stream...\n");
228	  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
229	  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
230	  if (ret < 0)
231	    {
232	      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
233	      goto err_free_buffers;
234	    }
235	
236	  printf("Streaming started\n");
237	
238	  /* Capture frames */
239	
240	  printf("Capturing %d frames...\n", TEST_CAPTURE_NUM);
241	  for (i = 0; i < TEST_CAPTURE_NUM; i++)
242	    {
243	      memset(&buf, 0, sizeof(buf));
244	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
245	      buf.memory = V4L2_MEMORY_USERPTR;
246	
247	      ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
248	      if (ret < 0)
249	        {
250	          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
251	          break;
252	        }
253	
254	      printf("Frame %d captured: %u bytes used\n", i, buf.bytesused);
255	
256	      /* Save frame to file */
257	
258	      ret = save_frame_to_file((const uint8_t *)buf.m.userptr,
259	                               buf.bytesused, i);
260	      if (ret < 0)
261	        {
262	          printf("WARNING: Failed to save frame %d\n", i);
263	        }
264	
265	      /* Requeue buffer */
266	
267	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
268	      if (ret < 0)
269	        {
270	          printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
271	          break;
272	        }
273	    }
274	
275	  /* Stop streaming */
276	
277	  printf("Stopping video stream...\n");
278	  ret = ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
279	  if (ret < 0)
280	    {
281	      printf("ERROR: VIDIOC_STREAMOFF failed: %d\n", errno);
282	    }
283	
284	  printf("Streaming stopped\n");
285	
286	  /* Cleanup */
287	
288	  printf("Test completed successfully!\n");
289	  printf("Captured %d frames to %s\n", i, TEST_SAVE_PATH);
290	
291	  ret = OK;
292	  goto err_free_buffers;
293	
294	err_free_buffers:
295	  for (i = 0; i < req.count; i++)
296	    {
297	      if (buffers[i].start != NULL)
298	        {
299	          free(buffers[i].start);
300	        }
301	    }
302	  free(buffers);
303	
304	err_close:
305	  close(fd);
306	  return ret;
307	}
