4333	/****************************************************************************
4334	 * Name: sunxi_transfer
4335	 *
4336	 * Description:
4337	 *   Process a request to handle a transfer descriptor.  This method will
4338	 *   enqueue the transfer request, blocking until the transfer completes.
4339	 *   Only one transfer may be  queued; Neither this method nor the ctrlin or
4340	 *   ctrlout methods can be called again until this function returns.
4341	 *
4342	 *   This is a blocking method; this functions will not return until the
4343	 *   transfer has completed.
4344	 *
4345	 * Input Parameters:
4346	 *   drvr   - The USB host driver instance obtained as a parameter from the
4347	 *            call to the class create() method.
4348	 *   ep     - The IN or OUT endpoint descriptor for the device endpoint on
4349	 *            which to perform the transfer.
4350	 *   buffer - A buffer containing the data to be sent (OUT endpoint) or
4351	 *            received (IN endpoint).  buffer must have been allocated using
4352	 *            DRVR_ALLOC
4353	 *   buflen - The length of the data to be sent or received.
4354	 *
4355	 * Returned Value:
4356	 *   On success, a non-negative value is returned that indicates the number
4357	 *   of bytes successfully transferred.  On a failure, a negated errno value
4358	 *   is returned that indicates the nature of the failure:
4359	 *
4360	 *     EAGAIN - If devices NAKs the transfer (or NYET or other error where
4361	 *              it may be appropriate to restart the entire transaction).
4362	 *     EPERM  - If the endpoint stalls
4363	 *     EIO    - On a TX or data toggle error
4364	 *     EPIPE  - Overrun errors
4365	 *
4366	 * Assumptions:
4367	 *   - Called from a single thread so no mutual exclusion is required.
4368	 *   - Never called from an interrupt handler.
4369	 *
4370	 ****************************************************************************/
4371	
4372	static ssize_t sunxi_transfer(struct usbhost_driver_s *drvr,
4373	                              usbhost_ep_t ep, uint8_t *buffer,
4374	                              size_t buflen)
4375	{
4376	  struct sunxi_rhport_s *rhport = (struct sunxi_rhport_s *)drvr;
4377	  struct sunxi_epinfo_s *epinfo = (struct sunxi_epinfo_s *)ep;
4378	  ssize_t nbytes;
4379	  int ret;
4380	
4381	  USB_ASSERT(rhport && epinfo && buffer && buflen > 0);
4382	
4383	  /* We must have exclusive access to the EHCI hardware and data
4384	   * structures.
4385	   */
4386	
4387	  ret = nxmutex_lock(&g_ehci.lock);
4388	  if (ret < 0)
4389	    {
4390	      return (ssize_t)ret;
4391	    }
4392	
4393	  /* Set the request for the IOC event well BEFORE initiating the
4394	   * transfer.
4395	   */
4396	
4397	  ret = sunxi_ioc_setup(rhport, epinfo);
4398	  if (ret != OK)
4399	    {
4400	      usbhost_trace1(EHCI_TRACE1_DEVDISCONNECTED, -ret);
4401	      goto errout_with_lock;
4402	    }
4403	
4404	  /* Initiate the transfer */
4405	
4406	  switch (epinfo->xfrtype)
4407	    {
4408	      case USB_EP_ATTR_XFER_BULK:
4409	        ret = sunxi_async_setup(rhport, epinfo, NULL, buffer, buflen);
4410	        break;
4411	
4412	#ifndef CONFIG_USBHOST_INT_DISABLE
4413	      case USB_EP_ATTR_XFER_INT:
4414	        ret = sunxi_intr_setup(rhport, epinfo, buffer, buflen);
4415	        break;
4416	#endif
4417	
4418	#ifndef CONFIG_USBHOST_ISOC_DISABLE
4419	      case USB_EP_ATTR_XFER_ISOC:
4420	# warning "Isochronous endpoint support not emplemented"
4421	#endif
4422	      case USB_EP_ATTR_XFER_CONTROL:
4423	      default:
4424	        usbhost_trace1(EHCI_TRACE1_BADXFRTYPE, epinfo->xfrtype);
4425	        ret = -ENOSYS;
4426	        break;
4427	    }
4428	
4429	  /* Check for errors in the setup of the transfer */
4430	
4431	  if (ret < 0)
4432	    {
4433	      goto errout_with_iocwait;
4434	    }
4435	
4436	  /* Then wait for the transfer to complete */
4437	
4438	  nbytes = sunxi_transfer_wait(epinfo);
4439	  nxmutex_unlock(&g_ehci.lock);
4440	  return nbytes;
4441	
4442	errout_with_iocwait:
4443	  epinfo->iocwait = false;
4444	errout_with_lock:
4445	  uerr("!!!\n");
4446	  nxmutex_unlock(&g_ehci.lock);
4447	  return (ssize_t)ret;
4448	}
