891	static int usbhost_uvc_stream_thread(int argc, FAR char *argv[])
892	{
893	  FAR struct usbhost_uvc_s *priv;
894	  FAR struct usbhost_hubport_s *hport;
895	  FAR struct usbhost_driver_s *drvr;
896	  ssize_t nbytes;
897	
898	  priv = (FAR struct usbhost_uvc_s *)
899	    ((uintptr_t)strtoul(argv[1], NULL, 16));
900	
901	  DEBUGASSERT(priv != NULL);
902	  hport = priv->usbclass.hport;
903	  DEBUGASSERT(hport != NULL && hport->drvr != NULL);
904	  drvr = hport->drvr;
905	
906	  uinfo("UVC stream thread started\n");
907	
908	  while (!priv->disconnected && priv->streaming)
909	    {
910	      /* Receive isochronous data */
911	
912	      nbytes = DRVR_TRANSFER(drvr, priv->ep_stream,
913	                             priv->xfer_buf, priv->xfer_buflen);
914	
915	      if (nbytes > 0)
916	        {
917	          usbhost_uvc_process_payload(priv, priv->xfer_buf, nbytes);
918	        }
919	      else if (nbytes < 0)
920	        {
921	          if (nbytes == -EAGAIN || nbytes == -ETIMEDOUT)
922	            {
923	              /* Retry on timeout - add delay to avoid busy wait */
924	
925	              nxsig_usleep(1000);  /* 1ms delay */
926	              continue;
927	            }
928	
929	          uerr("ERROR: Transfer failed: %zd\n", nbytes);
930	
931	          /* Break on serious errors */
932	
933	          if (nbytes == -ENODEV || nbytes == -EPIPE)
934	            {
935	              break;
936	            }
937	        }
938	    }
939	
940	  uinfo("UVC stream thread exiting\n");
941	  priv->stream_tid = 0;
942	  return OK;
943	}
