722	static int usbhost_uvc_start_streaming(FAR struct usbhost_uvc_s *priv)
723	{
724	  struct uvc_probe_commit_s probe;
725	  int ret;
726	
727	  syslog(LOG_INFO, "usbhost_uvc_start_streaming: Starting UVC streaming\n");
728	  syslog(LOG_INFO, "usbhost_uvc_start_streaming: format_idx=%d frame_idx=%d\n",
729	         priv->format_idx, priv->frame_idx);
730	
731	  /* Initialize probe structure */
732	
733	  memset(&probe, 0, sizeof(probe));
734	  probe.bFormatIndex = priv->format_idx;
735	  probe.bFrameIndex = priv->frame_idx;
736	  probe.dwFrameInterval = priv->cur_format.frame_interval;
737	
738	  /* Send PROBE_CONTROL SET_CUR */
739

738	  /* Send PROBE_CONTROL SET_CUR */
739	
740	  syslog(LOG_INFO, "usbhost_uvc_start_streaming: Sending PROBE SET_CUR\n");
741	  ret = usbhost_uvc_probe_commit(priv, UVC_SET_CUR, &probe);
742	  if (ret < 0)
743	    {
744	      syslog(LOG_ERR, "usbhost_uvc_start_streaming: PROBE SET_CUR failed: %d\n", ret);
745	      return ret;
746	    }
747	
748	  syslog(LOG_INFO, "usbhost_uvc_start_streaming: PROBE SET_CUR success\n");
749	
750	  /* Send PROBE_CONTROL GET_CUR to get negotiated values */
751	
752	  ret = usbhost_uvc_probe_commit(priv, UVC_GET_CUR, &probe);
753	  if (ret < 0)
754	    {
755	      uerr("ERROR: PROBE GET_CUR failed: %d\n", ret);
756	      return ret;
757	    }
758	
759	  priv->max_frame_size = probe.dwMaxVideoFrameSize;
760	  priv->max_payload_size = probe.dwMaxPayloadTransferSize;
761	
762	  uinfo("Negotiated: frame_size=%u payload_size=%u\n",
763	        (unsigned int)priv->max_frame_size, (unsigned int)priv->max_payload_size);
764	
765	  /* Send COMMIT_CONTROL SET_CUR */
766	
767	  probe.bFormatIndex = priv->format_idx;
768	  probe.bFrameIndex = priv->frame_idx;
769	  probe.dwFrameInterval = priv->cur_format.frame_interval;
770	
771	  ret = usbhost_uvc_probe_commit(priv, UVC_SET_CUR, &probe);
772	  if (ret < 0)
773	    {
774	      uerr("ERROR: COMMIT SET_CUR failed: %d\n", ret);
775	      return ret;
776	    }
777	
778	  /* Select the streaming alt setting to enable the endpoint */
779	
780	  ret = usbhost_uvc_set_interface(priv, priv->vs_ifno, 1);
781	  if (ret < 0)
782	    {
783	      uerr("ERROR: Failed to set streaming interface: %d\n", ret);
784	      return ret;
785	    }
786	
787	  priv->state = UVC_STATE_STREAMING;
788	  uinfo("UVC streaming started\n");
789	
790	  return OK;
791	}
