2140	static int sunxi_async_setup(struct sunxi_rhport_s *rhport,
2141	                             struct sunxi_epinfo_s *epinfo,
2142	                             const struct usb_ctrlreq_s *req,
2143	                             uint8_t *buffer, size_t buflen)
2144	{
2145	  struct sunxi_qh_s *qh;
2146	  struct sunxi_qtd_s *qtd;
2147	  uintptr_t physaddr;
2148	  uint32_t *flink;
2149	  uint32_t *alt;
2150	  uint32_t toggle;
2151	  bool dirin = false;
2152	  int ret;
2153	
2154	  syslog(LOG_INFO, "sunxi_async_setup: rhport=%p epinfo=%p req=%p buffer=%p buflen=%zu\n",
2155	         rhport, epinfo, req, buffer, buflen);
2156	
2157	  /* Terse output only if we are tracing */
2158	
2159	#ifdef CONFIG_USBHOST_TRACE
2160	  usbhost_vtrace2(EHCI_VTRACE2_ASYNCXFR, epinfo->epno, buflen);
2161	#else
2162	  uinfo("RHport%d EP%d: buffer=%p, buflen=%d, req=%p\n",
2163	        RHPORT(rhport), epinfo->epno, buffer, buflen, req);
2164	#endif
2165	
2166	  USB_ASSERT(rhport && epinfo);
2167	
2168	  /* A buffer may or may be supplied with an EP0 SETUP transfer.  A buffer
2169	   * will always be present for normal endpoint data transfers.
2170	   */
2171	
2172	  USB_ASSERT(req || (buffer && buflen > 0));
2173	
2174	  /* Create and initialize a Queue Head (QH) structure for this transfer */
2175	
2176	  syslog(LOG_INFO, "sunxi_async_setup: Creating QH\n");
2177	  qh = sunxi_qh_create(rhport, epinfo);
2178	  if (qh == NULL)
2179	    {
2180	      syslog(LOG_ERR, "sunxi_async_setup: QH creation failed\n");
2181	      usbhost_trace1(EHCI_TRACE1_QHCREATE_FAILED, 0);
2182	      return -ENOMEM;
2183	    }
2184	
2185	  syslog(LOG_INFO, "sunxi_async_setup: QH created: %p\n", qh);
2186	
2187	  /* Initialize the QH link and get the next data toggle (not used for SETUP
2188	   * transfers)
2189	   */
2190	
2191	  flink  = &qh->hw.overlay.nqp;
2192	  toggle = (uint32_t)epinfo->toggle << QTD_TOKEN_TOGGLE_SHIFT;
2193	  ret    = -EIO;
2194	
2195	  /* Is there an EP0 SETUP request?  If so, req will be non-NULL and we will
2196	   * queue two or three qTDs:
2197	   *
2198	   *   1) One for the SETUP phase,
2199	   *   2) One for the DATA phase (if there is data), and
2200	   *   3) One for the STATUS phase.
2201	   *
2202	   * If this is not an EP0 SETUP request, then only a data transfer will be
2203	   * enqueued.
2204	   */
2205	
2206	  if (req != NULL)
2207	    {
2208	      /* Allocate a new Queue Element Transfer Descriptor (qTD) for the SETUP
2209	       * phase of the request sequence.
2210	       */
2211	
2212	      qtd = sunxi_qtd_setupphase(epinfo, req);
2213	      if (qtd == NULL)
2214	        {
2215	          usbhost_trace1(EHCI_TRACE1_QTDSETUP_FAILED, 0);
2216	          goto errout_with_qh;
2217	        }
2218	
2219	      /* Link the new qTD to the QH head. */
2220	
2221	      physaddr = sunxi_physramaddr((uintptr_t)qtd);
2222	      *flink = sunxi_swap32(physaddr);
2223	
2224	      /* Get the new forward link pointer and data toggle */
2225	
2226	      flink  = &qtd->hw.nqp;
2227	      toggle = QTD_TOKEN_TOGGLE;
2228	    }
2229	
2230	  /* A buffer may or may be supplied with an EP0 SETUP transfer.  A buffer
2231	   * will always be present for normal endpoint data transfers.
2232	   */
2233	
2234	  alt = NULL;
2235	  if (buffer != NULL && buflen > 0)
2236	    {
2237	      uint32_t tokenbits;
2238	
2239	      /* Extra TOKEN bits include the data toggle, the data PID, and if
2240	       * there is no request, an indication to interrupt at the end of this
2241	       * transfer.
2242	       */
2243	
2244	      tokenbits = toggle;
2245	
2246	      /* Get the data token direction.
2247	       *
2248	       * If this is a SETUP request, use the direction contained in the
2249	       * request.  The IOC bit is not set.
2250	       */
2251	
2252	      if (req)
2253	        {
2254	          if ((req->type & USB_REQ_DIR_MASK) == USB_REQ_DIR_IN)
2255	            {
2256	              tokenbits |= QTD_TOKEN_PID_IN;
2257	              dirin      = true;
2258	            }
2259	          else
2260	            {
2261	              tokenbits |= QTD_TOKEN_PID_OUT;
2262	              dirin      = false;
2263	            }
2264	        }
2265	
2266	      /* Otherwise, the endpoint is uni-directional.  Get the direction from
2267	       * the epinfo structure.  Since this is not an EP0 SETUP request,
2268	       * nothing follows the data and we want the IOC interrupt when the
2269	       * data transfer completes.
2270	       */
2271	
2272	      else if (epinfo->dirin)
2273	        {
2274	          tokenbits |= (QTD_TOKEN_PID_IN | QTD_TOKEN_IOC);
2275	          dirin      = true;
2276	        }
2277	      else
2278	        {
2279	          tokenbits |= (QTD_TOKEN_PID_OUT | QTD_TOKEN_IOC);
2280	          dirin      = false;
2281	        }
2282	
2283	      /* Allocate a new Queue Element Transfer Descriptor (qTD) for the data
2284	       * buffer.
2285	       */
2286	
2287	      qtd = sunxi_qtd_dataphase(epinfo, buffer, buflen, tokenbits);
2288	      if (qtd == NULL)
2289	        {
2290	          usbhost_trace1(EHCI_TRACE1_QTDDATA_FAILED, 0);
2291	          goto errout_with_qh;
2292	        }
2293	
2294	      /* Link the new qTD to either QH head of the SETUP qTD. */
2295	
2296	      physaddr = sunxi_physramaddr((uintptr_t)qtd);
2297	      *flink = sunxi_swap32(physaddr);
2298	
2299	      /* Set the forward link pointer to this new qTD */
2300	
2301	      flink = &qtd->hw.nqp;
2302	
2303	      /* If this was an IN transfer, then setup a pointer alternate link.
2304	       * The EHCI hardware will use this link if a short packet is received.
2305	       */
2306	
2307	      if (dirin)
2308	        {
2309	          alt = &qtd->hw.alt;
2310	        }
2311	    }
2312	
2313	  /* If this is an EP0 SETUP request, then enqueue one more qTD for the
2314	   * STATUS phase transfer.
2315	   */
2316	
2317	  if (req != NULL)
2318	    {
2319	      /* Extra TOKEN bits include the data toggle and the correct data PID. */
2320	
2321	      uint32_t tokenbits = toggle;
2322	
2323	      /* The status phase direction is the opposite of the data phase.  If
2324	       * this is an IN request, then we received the buffer and we will send
2325	       * the zero length packet handshake.
2326	       */
2327	
2328	      if ((req->type & USB_REQ_DIR_MASK) == USB_REQ_DIR_IN)
2329	        {
2330	          tokenbits |= QTD_TOKEN_PID_OUT;
2331	        }
2332	
2333	      /* Otherwise, this in an OUT request.  We send the buffer and we expect
2334	       * to receive the NULL packet handshake.
2335	       */
2336	
2337	      else
2338	        {
2339	          tokenbits |= QTD_TOKEN_PID_IN;
2340	        }
2341	
2342	      /* Allocate a new Queue Element Transfer Descriptor (qTD)
2343	       * for the status
2344	       */
2345	
2346	      qtd = sunxi_qtd_statusphase(tokenbits);
2347	      if (qtd == NULL)
2348	        {
2349	          usbhost_trace1(EHCI_TRACE1_QTDSTATUS_FAILED, 0);
2350	          goto errout_with_qh;
2351	        }
2352	
2353	      /* Link the new qTD to either the SETUP or data qTD. */
2354	
2355	      physaddr = sunxi_physramaddr((uintptr_t)qtd);
2356	      *flink = sunxi_swap32(physaddr);
2357	
2358	      /* In an IN data qTD was also enqueued, then linked the data qTD's
2359	       * alternate pointer to this STATUS phase qTD in order to handle short
2360	       * transfers.
2361	       */
2362	
2363	      if (alt)
2364	        {
2365	          *alt = sunxi_swap32(physaddr);
2366	        }
2367	    }
2368	
2369	  /* Add the new QH to the head of the asynchronous queue list */
2370	
2371	  syslog(LOG_INFO, "sunxi_async_setup: Enqueueing QH\n");
2372	  sunxi_qh_enqueue(&g_asynchead, qh);
2373	  syslog(LOG_INFO, "sunxi_async_setup: QH enqueued successfully\n");
2374	  return OK;
2375	
2376	  /* Clean-up after an error */
2377	
2378	errout_with_qh:
2379	  sunxi_qh_discard(qh);
2380	  return ret;
2381	}
