1869	{
1870	  uint32_t physaddr;
1871	  uint32_t nbytes;
1872	  uint32_t next;
1873	  int ndx;
1874	
1875	  /* Flush the contents of the data buffer to RAM so that the correct
1876	   * contents will be accessed for an OUT DMA.
1877	   */
1878	
1879	  up_flush_dcache((uintptr_t)buffer, (uintptr_t)buffer + buflen);
1880	
1881	  /* Loop, adding the aligned physical addresses of the buffer to the buffer
1882	   * page list.  Only the first entry need not be aligned (because only the
1883	   * first entry has the offset field). The subsequent entries must begin on
1884	   * 4KB address boundaries.
1885	   */
1886	
1887	  physaddr = (uint32_t)sunxi_physramaddr((uintptr_t)buffer);
1888	
1889	  for (ndx = 0; ndx < 5; ndx++)
1890	    {
1891	      /* Write the physical address of the buffer into the qTD buffer pointer
1892	       * list.
1893	       */
1894	
