 *   Free an iTD structure by returning it to the free list.
 *
 * Assumption:  Caller holds the lock
 *
 ****************************************************************************/

static void sunxi_itd_free(struct sunxi_itd_s *itd)
{
  struct sunxi_list_s *entry = (struct sunxi_list_s *)itd;

  entry->flink  = g_ehci.itdfree;
  g_ehci.itdfree = entry;
}

/****************************************************************************
 * Name: sunxi_isoc_setup
 *
 * Description:
 *   Process an IN or OUT request on an isochronous endpoint by creating an
 *   iTD and linking it into the periodic frame list.
 *
 *   Per EHCI spec paragraph 3.3, iTDs are used for high-speed isochronous
 *   transfers. Each iTD can handle up to 8 micro-frame transactions.
 *
 * Assumption:  The caller holds the EHCI lock.
 *
 ****************************************************************************/

static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
                            struct sunxi_epinfo_s *epinfo,
                            uint8_t *buffer, size_t buflen)
{
  struct sunxi_itd_s *itd;
  uintptr_t physaddr;
  uint32_t regval;
  uint32_t frindex;
  int frame_ndx;
  int ret;

  uinfo("RHport%d EP%d: isoc buffer=%p, buflen=%zu\n",
        RHPORT(rhport), epinfo->epno, buffer, buflen);

  USB_ASSERT(rhport && epinfo && buffer && buflen > 0);

  /* UVC isochronous: buflen should not exceed what one iTD can handle.
   * One iTD covers up to 8 transactions, each up to maxpacket bytes.
   * For UVC, typical maxpacket is 1024 bytes, so max = 8*1024 = 8KB.
   */

  if (buflen > (size_t)epinfo->maxpacket * 8)
    {
      uerr("ERROR: buflen %zu exceeds iTD capacity %d\n",
           buflen, epinfo->maxpacket * 8);
      return -EFBIG;
    }

  /* Allocate an iTD */

  itd = sunxi_itd_alloc();
  if (itd == NULL)
    {
      uerr("ERROR: Failed to allocate iTD\n");
      return -ENOMEM;
    }

  /* Save endpoint info and buffer references */

  itd->epinfo = epinfo;
  itd->buffer = buffer;
  itd->buflen = buflen;
  itd->result = -EBUSY;

  /* Flush the data buffer to RAM for DMA */

  up_flush_dcache((uintptr_t)buffer, (uintptr_t)buffer + buflen);

  /* Get the physical address of the buffer */

  physaddr = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);

  /* Fill iTD Buffer Page Pointer List (bpl[0..6])
   *
   * bpl[0]: Bits 0-6 = Device Address, Bits 8-11 = Endpoint Number,
   *         Bits 12-31 = Buffer Pointer (page 0)
   * bpl[1]: Bits 0-10 = Max Packet Size, Bit 11 = Direction (1=IN),
   *         Bits 12-31 = Buffer Pointer (page 1)
   * bpl[2]: Bits 0-1 = Multi (transactions per micro-frame),
   *         Bits 12-31 = Buffer Pointer (page 2)
   * bpl[3..6]: Bits 12-31 = Buffer Pointer (pages 3-6)
   */

  itd->hw.bpl[0] = sunxi_swap32(
    ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
    ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
    (physaddr & ITD_BUFPTR_MASK));

  itd->hw.bpl[1] = sunxi_swap32(
    ((uint32_t)epinfo->maxpacket << ITD_BUFPTR1_MAXPKT_SHIFT) |
    (epinfo->dirin ? ITD_BUFPTR1_DIRIN : 0) |
    ((physaddr + 4096) & ITD_BUFPTR_MASK));

  itd->hw.bpl[2] = sunxi_swap32(
    ITD_BUFPTR2_MULTI_1 |
    ((physaddr + 8192) & ITD_BUFPTR_MASK));

  itd->hw.bpl[3] = sunxi_swap32((physaddr + 12288) & ITD_BUFPTR_MASK);
  itd->hw.bpl[4] = sunxi_swap32((physaddr + 16384) & ITD_BUFPTR_MASK);
  itd->hw.bpl[5] = sunxi_swap32((physaddr + 20480) & ITD_BUFPTR_MASK);
  itd->hw.bpl[6] = sunxi_swap32((physaddr + 24576) & ITD_BUFPTR_MASK);

  /* Fill Transaction[0] for the single transfer:
   *
   * Bits 0-11:   Offset within page
   * Bits 12-14:  Page select (0-6)
   * Bit 15:      IOC (Interrupt On Completion)
   * Bits 16-27:  Transaction length
   * Bit 31:      ACTIVE
   */

  regval = (physaddr & 0xfff) |                    /* Offset within page 0 */
           (0 << ITD_TRAN_PG_SHIFT) |              /* Page 0 */
           ITD_TRAN_IOC |                           /* Interrupt on complete */
           ((uint32_t)buflen << ITD_TRAN_LENGTH_SHIFT) |
           ITD_TRAN_STATUS_ACTIVE;                  /* Active */

  itd->hw.trans[0] = sunxi_swap32(regval);

  /* Mark remaining transactions as inactive */

  itd->hw.trans[1] = 0;
  itd->hw.trans[2] = 0;
  itd->hw.trans[3] = 0;
  itd->hw.trans[4] = 0;
  itd->hw.trans[5] = 0;
  itd->hw.trans[6] = 0;
  itd->hw.trans[7] = 0;

  /* Set Next Link Pointer to terminate (no more iTDs in chain) */

  itd->hw.nlp = sunxi_swap32(ITD_NLP_T);

  /* Flush the iTD to RAM */

  up_flush_dcache((uintptr_t)&itd->hw,
                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

  /* Save as the active iTD for IOC completion checking */

  g_active_itd = itd;

  /* Link the iTD into the periodic frame list.
   *
   * Read the current frame index and schedule the iTD a few frames ahead
   * to ensure the host controller sees it in time.
   */

  frindex = sunxi_swap32(sunxi_getreg(&HCOR->frindex));
  frame_ndx = ((frindex >> 3) + 2) & (FRAME_LIST_SIZE - 1);

  physaddr = sunxi_physramaddr((uintptr_t)&itd->hw);

  /* Temporarily disable the periodic schedule to safely modify the frame
   * list entry.
   */

  regval  = sunxi_getreg(&HCOR->usbcmd);
  regval &= ~EHCI_USBCMD_PSEN;
  sunxi_putreg(regval, &HCOR->usbcmd);

  /* Link iTD to the frame list entry. The iTD's next pointer terminates,
   * so it's the only entry in this frame slot.
   */

  g_framelist[frame_ndx] = sunxi_swap32(physaddr) | PFL_TYP_ITD;

  up_flush_dcache((uintptr_t)&g_framelist[frame_ndx],
                  (uintptr_t)&g_framelist[frame_ndx] + sizeof(uint32_t));

  /* Re-enable the periodic schedule */

  regval |= EHCI_USBCMD_PSEN;
  sunxi_putreg(regval, &HCOR->usbcmd);

  uinfo("iTD scheduled at frame %d, physaddr=%p\n", frame_ndx,
        (void *)(uintptr_t)physaddr);

  return OK;
}
