      struct sunxi_itd_s *itd = g_active_itd;
      struct sunxi_epinfo_s *epinfo = itd->epinfo;
      uint32_t tran;
      uint32_t status;

      /* Invalidate the iTD cache */

      up_invalidate_dcache((uintptr_t)&itd->hw,
                           (uintptr_t)&itd->hw +
                           sizeof(struct ehci_itd_s));

      /* Check transaction[0] status */

      tran   = sunxi_swap32(itd->hw.trans[0]);
      status = tran & ITD_TRAN_STATUS_MASK;

      /* Is the transaction still active? */

      if ((status & ITD_TRAN_STATUS_ACTIVE) != 0)
        {
          /* Still active, nothing to do */
          return;
        }

      /* Transaction completed. Calculate bytes transferred.
       * The LENGTH field in the transaction status contains the
       * number of bytes NOT transferred. So transferred = total - remaining.
       */

      {
        uint32_t remaining = (tran & ITD_TRAN_LENGTH_MASK) >>
                             ITD_TRAN_LENGTH_SHIFT;
        itd->xfrd = itd->buflen - remaining;
      }

      /* Check for errors */

      if (status & (ITD_TRAN_STATUS_XACTERR |
                    ITD_TRAN_STATUS_BABBLE |
                    ITD_TRAN_STATUS_DBERROR))
        {
          if (status & ITD_TRAN_STATUS_BABBLE)
            {
              epinfo->result = -EPIPE;
            }
          else
            {
              epinfo->result = -EIO;
            }
        }
      else
        {
          epinfo->xfrd   = itd->xfrd;
          epinfo->result = OK;
        }

      /* Free the iTD */

      sunxi_itd_free(itd);
      g_active_itd = NULL;

      /* Wake up the thread waiting for this transfer */

      if (epinfo->iocwait)
        {
          epinfo->iocwait = false;
          nxsem_post(&epinfo->iocsem);
        }
