static struct sunxi_itd_s *sunxi_itd_alloc(void)
{
  struct sunxi_itd_s *itd = (struct sunxi_itd_s *)g_ehci.itdfree;
  if (itd)
    {
      g_ehci.itdfree = ((struct sunxi_list_s *)itd)->flink;
      memset(itd, 0, sizeof(struct sunxi_itd_s));
    }
  return itd;
}

static void sunxi_itd_free(struct sunxi_itd_s *itd)
{
  struct sunxi_list_s *entry = (struct sunxi_list_s *)itd;
  entry->flink  = g_ehci.itdfree;
  g_ehci.itdfree = entry;
}

static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
                            struct sunxi_epinfo_s *epinfo,
                            uint8_t *buffer, size_t buflen)
{
  struct sunxi_itd_s *itd;
  uintptr_t physaddr;
  uintptr_t bufphys;
  uint32_t regval;
  uint32_t frindex;
  int frame_ndx;

  uinfo("isoc_setup: ep%d buflen=%zu\n", epinfo->epno, buflen);

  if (buflen == 0 || buflen > (size_t)epinfo->maxpacket * 8)
    {
      return -EINVAL;
    }

  itd = sunxi_itd_alloc();
  if (itd == NULL)
    {
      return -ENOMEM;
    }

  itd->epinfo = epinfo;
  itd->buffer = buffer;
  itd->buflen = buflen;
  itd->result = -EBUSY;

  up_flush_dcache((uintptr_t)buffer, (uintptr_t)buffer + buflen);
  bufphys = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);

  /* bpl[0]: devaddr + endpoint + page 0 base */

  itd->hw.bpl[0] = sunxi_swap32(
    ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
    ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
    (bufphys & ITD_BUFPTR_MASK));

  /* bpl[1]: maxpkt + direction + page 1 base */

  itd->hw.bpl[1] = sunxi_swap32(
    ((uint32_t)epinfo->maxpacket << ITD_BUFPTR1_MAXPKT_SHIFT) |
    (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
    ((bufphys + 0x1000) & ITD_BUFPTR_MASK));

  /* bpl[2]: multi=1 + page 2 base */

  itd->hw.bpl[2] = sunxi_swap32(
    ITD_BUFPTR2_MULTI_1 |
    ((bufphys + 0x2000) & ITD_BUFPTR_MASK));

  /* bpl[3..6]: pages 3-6 */

  itd->hw.bpl[3] = sunxi_swap32((bufphys + 0x3000) & ITD_BUFPTR_MASK);
  itd->hw.bpl[4] = sunxi_swap32((bufphys + 0x4000) & ITD_BUFPTR_MASK);
  itd->hw.bpl[5] = sunxi_swap32((bufphys + 0x5000) & ITD_BUFPTR_MASK);
  itd->hw.bpl[6] = sunxi_swap32((bufphys + 0x6000) & ITD_BUFPTR_MASK);

  /* trans[0]: offset + page0 + IOC + length + ACTIVE */

  regval = (bufphys & 0xfff) |
           (0 << ITD_TRAN_PG_SHIFT) |
           ITD_TRAN_IOC |
           ((uint32_t)buflen << ITD_TRAN_LENGTH_SHIFT) |
           ITD_TRAN_STATUS_ACTIVE;
  itd->hw.trans[0] = sunxi_swap32(regval);

  /* Remaining transactions inactive */

  itd->hw.trans[1] = 0;
  itd->hw.trans[2] = 0;
  itd->hw.trans[3] = 0;
  itd->hw.trans[4] = 0;
  itd->hw.trans[5] = 0;
  itd->hw.trans[6] = 0;
  itd->hw.trans[7] = 0;

  itd->hw.nlp = sunxi_swap32(ITD_NLP_T);

  up_flush_dcache((uintptr_t)&itd->hw,
                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

  g_active_itd = itd;

  /* Link iTD into periodic frame list */

  frindex = sunxi_swap32(sunxi_getreg(&HCOR->frindex));
  frame_ndx = ((frindex >> 3) + 3) & (FRAME_LIST_SIZE - 1);
  physaddr = sunxi_physramaddr((uintptr_t)&itd->hw);

  regval = sunxi_getreg(&HCOR->usbcmd);
  sunxi_putreg(regval & ~EHCI_USBCMD_PSEN, &HCOR->usbcmd);

  g_framelist[frame_ndx] = sunxi_swap32(physaddr) | PFL_TYP_ITD;
  up_flush_dcache((uintptr_t)&g_framelist[frame_ndx],
                  (uintptr_t)&g_framelist[frame_ndx] + 4);

  sunxi_putreg(regval | EHCI_USBCMD_PSEN, &HCOR->usbcmd);

  uinfo("isoc_setup: scheduled at frame %d\n", frame_ndx);
  return OK;
}

