/* Limit transfer to what one iTD can handle: maxpacket per micro-frame,
 * up to 8 micro-frames per iTD = maxpacket * 8 bytes max.
 */

if (buflen > (size_t)epinfo->maxpacket * 8)
  {
    buflen = (size_t)epinfo->maxpacket * 8;
  }

syslog(LOG_ERR, "isoc_setup: ep%d dirin=%d buflen=%zu maxpkt=%d\n",
       epinfo->epno, epinfo->dirin, buflen, epinfo->maxpacket);

if (buflen == 0)
  {
    return -EINVAL;
  }

