 * IOC is set on the last active transaction only.
 * Page select and offset are computed from the buffer address.
 */

{
  int ntrans = (buflen + epinfo->maxpacket - 1) / epinfo->maxpacket;
  int i;
  uint32_t off = bufphys & 0xfff;
  uint32_t pg   = 0;

  for (i = 0; i < 8; i++)
    {
      if (i < ntrans)
        {
          uint32_t xlen = (uint32_t)(buflen > epinfo->maxpacket ?
                           epinfo->maxpacket : buflen);
          uint32_t flags = (off & ITD_TRAN_XOFFS_MASK) |
                           (pg << ITD_TRAN_PG_SHIFT) |
                           (xlen << ITD_TRAN_LENGTH_SHIFT) |
