            }
          itd->hw.trans[i] = sunxi_swap32(flags);
          buflen -= xlen;
          off += xlen;
          if (off >= 4096)
            {
              off -= 4096;
              pg++;
            }
        }
      else
        {
          itd->hw.trans[i] = 0;
        }
    }
}

