  /* Check active iTD for isochronous transfer completion.
   * Scan all 8 transactions. If ANY has data transferred (not ACTIVE),
   * treat as completion.
   */

  if (g_active_itd != NULL)
    {
      struct sunxi_itd_s *itd = g_active_itd;
      struct sunxi_epinfo_s *epinfo = itd->epinfo;
      bool any_done = false;
      bool any_active = false;
      uint32_t total_xfrd = 0;
      bool has_error = false;
      int uf;

      up_invalidate_dcache((uintptr_t)&itd->hw,
                           (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

      for (uf = 0; uf < 8; uf++)
        {
          uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
          uint32_t status = tran & ITD_TRAN_STATUS_MASK;
          uint32_t xlen;

          if (tran == 0)
            {
              break;  /* No more active transactions */
            }

          xlen = (tran & ITD_TRAN_LENGTH_MASK) >> ITD_TRAN_LENGTH_SHIFT;

          if ((status & ITD_TRAN_STATUS_ACTIVE) != 0)
            {
              any_active = true;
              /* Check if partial data was received */
              if (xlen < ((tran >> 16) & 0xfff))
                {
                  total_xfrd += (((tran >> 16) & 0xfff) - xlen);
                  any_done = true;
                }
            }
          else
            {
              /* Transaction completed */
              uint32_t requested = (tran >> 16) & 0xfff;
              total_xfrd += (requested - xlen);
              any_done = true;

              if (status & (ITD_TRAN_STATUS_XACTERR |
                            ITD_TRAN_STATUS_BABBLE |
                            ITD_TRAN_STATUS_DBERROR))
                {
                  has_error = true;
                }
            }
        }

      syslog(LOG_ERR, "iTD check: done=%d active=%d xfrd=%u err=%d\n",
             any_done, any_active, total_xfrd, has_error);

      if (any_done && total_xfrd > 0)
        {
          epinfo->xfrd   = total_xfrd;
          epinfo->result = has_error ? -EIO : OK;

          if (itd->buffer != NULL && total_xfrd > 0)
            {
              up_invalidate_dcache((uintptr_t)itd->buffer,
                                   (uintptr_t)itd->buffer + total_xfrd);
            }

          sunxi_itd_free(itd);
          g_active_itd = NULL;

          if (epinfo->iocwait)
            {
              epinfo->iocwait = false;
              nxsem_post(&epinfo->iocsem);
            }

