input.new_string:
static int sunxi_ioc_wait(struct sunxi_epinfo_s *epinfo)
{
  int ret = OK;

  /* Wait for the IOC event.  Loop to handle any false alarm semaphore
   * counts.  For isochronous transfers, also poll the iTD status since
   * the EHCI controller may not generate IOC interrupts for iTDs.
   * Return an error if the task is canceled.
   */

  while (epinfo->iocwait)
    {
#ifndef CONFIG_USBHOST_ISOC_DISABLE
      /* If an iTD is active, poll its status periodically */

      if (g_active_itd != NULL && g_active_itd->epinfo == epinfo)
        {
          ret = nxsem_tickwait_uninterruptible(&epinfo->iocsem,
                                               MSEC2TICK(5));
          if (ret == -ETIMEDOUT)
            {
              /* Timed out — check the iTD directly */

              struct sunxi_itd_s *itd = g_active_itd;
              uint32_t tran;
              uint32_t total_xfrd = 0;
              bool any_done = false;
              int uf;

              up_invalidate_dcache((uintptr_t)&itd->hw,
                (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

              for (uf = 0; uf < 8; uf++)
                {
                  tran = sunxi_swap32(itd->hw.trans[uf]);
                  if (tran == 0)
                    {
                      break;
                    }

                  if ((tran & ITD_TRAN_STATUS_ACTIVE) == 0)
                    {
                      uint32_t req = (tran >> 16) & 0xfff;
                      uint32_t rem = (tran & ITD_TRAN_LENGTH_MASK) >>
                                     ITD_TRAN_LENGTH_SHIFT;
                      total_xfrd += (req - rem);
                      any_done = true;
                    }
                }

              if (any_done && total_xfrd > 0)
                {
                  epinfo->xfrd   = total_xfrd;
                  epinfo->result = OK;
                  epinfo->iocwait = false;

                  if (itd->buffer != NULL)
                    {
                      up_invalidate_dcache((uintptr_t)itd->buffer,
                        (uintptr_t)itd->buffer + total_xfrd);
                    }

                  sunxi_itd_free(itd);
                  g_active_itd = NULL;
                  syslog(LOG_ERR, "iTD poll: xfrd=%u\n", total_xfrd);
                  return epinfo->result;
                }

              continue;  /* Still waiting, try again */
            }
        }
      else
#endif
        {
          ret = nxsem_wait_uninterruptible(&epinfo->iocsem);
        }

      if (ret < 0)
        {
          break;
        }
    }

  return ret < 0 ? ret : epinfo->result;
}

