g_active_itd = itd;

/* Stop the controller, update frame list, restart.
 * This is the most reliable way to ensure the controller sees the new iTD.
 */

frame_ndx = 0;  /* Always use frame 0 */
physaddr = sunxi_physramaddr((uintptr_t)&itd->hw);

/* Save the existing frame list entry (points to interrupt QH) */

{
  uint32_t old_entry = sunxi_swap32(g_framelist[frame_ndx]);

