  itd->hw.nlp = sunxi_swap32(old_entry);

  /* Write-back the iTD to RAM */

  up_clean_dcache((uintptr_t)&itd->hw,
                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
  UP_DSB();

  /* Stop the controller */

  regval = sunxi_getreg(&HCOR->usbcmd);
  regval &= ~EHCI_USBCMD_RUN;
  sunxi_putreg(regval, &HCOR->usbcmd);
  ehci_wait_usbsts(EHCI_USBSTS_HALTED, EHCI_USBSTS_HALTED, 100 * 1000);

  /* Update frame list entry */

  g_framelist[frame_ndx] = sunxi_swap32(physaddr) | PFL_TYP_ITD;
  up_clean_dcache((uintptr_t)&g_framelist[frame_ndx],
                  (uintptr_t)&g_framelist[frame_ndx] + 4);

  /* Update periodic list base address */

  physaddr = sunxi_physramaddr((uintptr_t)g_framelist);
  sunxi_putreg(sunxi_swap32(physaddr), &HCOR->periodiclistbase);

  /* Restart the controller with periodic schedule enabled */

  regval = sunxi_getreg(&HCOR->usbcmd);
  regval |= (EHCI_USBCMD_RUN | EHCI_USBCMD_PSEN | EHCI_USBCMD_ASEN);
  sunxi_putreg(regval, &HCOR->usbcmd);

  /* Wait for controller to start running */

  ehci_wait_usbsts(EHCI_USBSTS_HALTED, 0, 100 * 1000);
  UP_DSB();
}

