This walks the per-frame shadow/hardware lists to find the insertion point (after iso nodes, before any QH). It links the iTD into both the software shadow list and the hardware periodic list, ending with a write memory barrier before updating the hardware pointer.

## 2. `itd_patch()` — Setting Up Buffer Pointers and Transactions

```c
static inline void
itd_patch(
	struct ehci_hcd		*ehci,
	struct ehci_itd		*itd,
	struct ehci_iso_sched	*iso_sched,
	unsigned		index,
	u16			uframe
)
{
	struct ehci_iso_packet	*uf = &iso_sched->packet[index];
	unsigned		pg = itd->pg;

	uframe &= 0x07;
	itd->index[uframe] = index;

	itd->hw_transaction[uframe] = uf->transaction;
	itd->hw_transaction[uframe] |= cpu_to_hc32(ehci, pg << 12);
	itd->hw_bufp[pg] |= cpu_to_hc32(ehci, uf->bufp & ~(u32)0);
	itd->hw_bufp_hi[pg] |= cpu_to_hc32(ehci, (u32)(uf->bufp >> 32));

	if (unlikely(uf->cross)) {
		u64	bufp = uf->bufp + 4096;

		itd->pg = ++pg;
		itd->hw_bufp[pg] |= cpu_to_hc32(ehci, bufp & ~(u32)0);
		itd->hw_bufp_hi[pg] |= cpu_to_hc32(ehci, (u32)(bufp >> 32));
	}
}
```

The companion `itd_sched_init()` pre-calculates the transaction words from URB descriptors:

```c
trans = EHCI_ISOC_ACTIVE;
trans |= buf & 0x0fff;
if (unlikely(((i + 1) == urb->number_of_packets))
        && !(urb->transfer_flags & URB_NO_INTERRUPT))
    trans |= EHCI_ITD_IOC;
trans |= length << 16;
uframe->transaction = cpu_to_hc32(ehci, trans);

uframe->bufp = (buf & ~(u64)0x0fff);
```

Each packet maps to a microframe slot (0–7). Page-crossing packets consume an additional buffer page pointer entry. The page field (`pg << 12`) is OR'd into the transaction word.

## 3. `itd_complete()` — Completion Detection and Processing

```c
static bool itd_complete(struct ehci_hcd *ehci, struct ehci_itd *itd)
{
	struct urb				*urb = itd->urb;
	struct usb_iso_packet_descriptor	*desc;
	u32					t;
	unsigned				uframe;
	int					urb_index = -1;
	struct ehci_iso_stream			*stream = itd->stream;
	bool					retval = false;

	for (uframe = 0; uframe < 8; uframe++) {
		if (likely(itd->index[uframe] == -1))
			continue;
		urb_index = itd->index[uframe];
		desc = &urb->iso_frame_desc[urb_index];

		t = hc32_to_cpup(ehci, &itd->hw_transaction[uframe]);
		itd->hw_transaction[uframe] = 0;

		if (unlikely(t & ISO_ERRS)) {
			urb->error_count++;
			if (t & EHCI_ISOC_BUF_ERR)
				desc->status = usb_pipein(urb->pipe)
					? -ENOSR : -ECOMM;
			else if (t & EHCI_ISOC_BABBLE)
				desc->status = -EOVERFLOW;
			else
				desc->status = -EPROTO;
			if (!(t & EHCI_ISOC_BABBLE)) {
				desc->actual_length = EHCI_ITD_LENGTH(t);
				urb->actual_length += desc->actual_length;
			}
		} else if (likely((t & EHCI_ISOC_ACTIVE) == 0)) {
			desc->status = 0;
			desc->actual_length = EHCI_ITD_LENGTH(t);
			urb->actual_length += desc->actual_length;
		} else {
			urb->error_count++;
		}
	}

	if (likely((urb_index + 1) != urb->number_of_packets))
		goto done;

	ehci_urb_done(ehci, urb, 0);
	retval = true;
	/* ... bandwidth accounting, disable_periodic ... */

done:
	itd->urb = NULL;
	list_move_tail(&itd->itd_list, &stream->free_list);

	if (list_empty(&stream->td_list)) {
		list_splice_tail_init(&stream->free_list,
				&ehci->cached_itd_list);
		start_free_itds(ehci);
	}
	return retval;
}
```

The caller `scan_isoc()` determines whether an iTD is complete by checking the ACTIVE bit:

```c
if (frame == now_frame && live) {
    rmb();
    for (uf = 0; uf < 8; uf++) {
        if (q.itd->hw_transaction[uf] &
                ITD_ACTIVE(ehci))
            break;
    }
    if (uf < 8) {
        /* skip — still active */
    }
}
```

Active iTDs are left in the schedule; finished ones are unlinked from the hardware list and passed to `itd_complete()`.

## 4. Memory Barriers and Cache Operations

The code uses several memory barriers to ensure ordering between software state and hardware-visible DMA structures:

| Barrier | Location | Purpose |
|---------|----------|---------|
| `wmb()` | `itd_link()` | Ensures iTD fields are written before the hardware periodic pointer is updated |
| `wmb()` | `sitd_link()` | Same pattern for split-iso TDs |
| `wmb()` | `qh_link_periodic()` | Ensures QH next pointers are set before linking into hardware list |
| `rmb()` | `scan_isoc()` | Ensures reads of `hw_transaction[]` see hardware-updated values before checking ACTIVE |
| `wmb()` | `scan_isoc()` | After unlinking an ITD/SITD from the list, before processing completion |
| `wmb()` | `start_unlink_intr()` | "Make sure the unlinks are visible before starting the timer" |

There are no explicit cache flush/invalidate operations. The EHCI driver relies on consistent DMA mappings created via `dma_pool_alloc()`, which handle cache coherency through the platform's DMA API. All hardware-facing fields use the `__hc32` type with `cpu_to_hc32()`/`hc32_to_cpu()` endian conversion macros.

