151	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
152	  if (ret < 0)
153	    {
154	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
155	      goto err_close;
156	    }
157	
158	  printf("Format set successfully\n");
159	  printf("  Actual size: %dx%d\n", fmt.fmt.pix.width, fmt.fmt.pix.height);
160	  printf("  Bytes per line: %d\n", fmt.fmt.pix.bytesperline);
161	  printf("  Image size: %d\n", fmt.fmt.pix.sizeimage);
162	
