164	
165	  if (fmt.fmt.pix.sizeimage == 0)
166	    {
167	      fmt.fmt.pix.sizeimage = fmt.fmt.pix.width * fmt.fmt.pix.height * 2;
168	      printf("  Computed image size: %d (YUYV)\n", fmt.fmt.pix.sizeimage);
169	    }
