189	
190	  buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
191	  if (buffers == NULL)
192	    {
193	      printf("ERROR: Failed to allocate buffer array\n");
194	      goto err_close;
195	    }
196	
197	  for (i = 0; i < req.count; i++)
198	    {
199	      buffers[i].length = fmt.fmt.pix.sizeimage;
200	      buffers[i].start = (uint8_t *)memalign(32, buffers[i].length);
201	      if (buffers[i].start == NULL)
202	        {
