/****************************************************************************
 * apps/examples/uvc_test/uvc_test.c
 *
 * USB Camera (UVC) live preview on framebuffer/LCD
 * Captures YUYV frames and displays them on /dev/lcd0 in real time.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>
#include <nuttx/video/fb.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VIDEO_DEV_PATH    "/dev/video"
#define FB_DEV_PATH       "/dev/lcd0"
#define TEST_WIDTH        320
#define TEST_HEIGHT       240
#define TEST_BUF_COUNT    3
#define PREVIEW_FRAMES    300   /* ~10s at 30fps; 0 = run forever */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct v_buffer
{
  uint8_t *start;
  uint32_t length;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct fb_videoinfo_s g_vinfo;
static struct fb_planeinfo_s g_pinfo;
static FAR uint8_t          *g_fbmem;
static int                   g_fbfd = -1;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Clamp an int to [0,255] */

static inline uint8_t clamp8(int v)
{
  if (v < 0)
    {
      return 0;
    }

  if (v > 255)
    {
      return 255;
    }

  return (uint8_t)v;
}

/****************************************************************************
 * Name: fb_open
 *
 * Description:
 *   Open the framebuffer device and query its geometry.
 *
 ****************************************************************************/

static int fb_open(void)
{
  int ret;

  g_fbfd = open(FB_DEV_PATH, O_RDWR);
  if (g_fbfd < 0)
    {
      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
      return -errno;
    }

  ret = ioctl(g_fbfd, FBIOGET_VIDEOINFO, (uintptr_t)&g_vinfo);
  if (ret < 0)
    {
      printf("ERROR: FBIOGET_VIDEOINFO failed: %d\n", errno);
      close(g_fbfd);
      g_fbfd = -1;
      return -errno;
    }

  ret = ioctl(g_fbfd, FBIOGET_PLANEINFO, (uintptr_t)&g_pinfo);
  if (ret < 0)
    {
      printf("ERROR: FBIOGET_PLANEINFO failed: %d\n", errno);
      close(g_fbfd);
      g_fbfd = -1;
      return -errno;
    }

  printf("FB: %ux%u bpp=%u fmt=%u stride=%u fblen=%zu\n",
         g_vinfo.xres, g_vinfo.yres, g_pinfo.bpp, g_vinfo.fmt,
         g_pinfo.stride, g_pinfo.fblen);

  g_fbmem = (FAR uint8_t *)g_pinfo.fbmem;
  if (g_fbmem == NULL)
    {
      /* Some drivers require mmap to obtain the framebuffer memory */

      g_fbmem = mmap(NULL, g_pinfo.fblen, PROT_READ | PROT_WRITE,
                     MAP_SHARED, g_fbfd, 0);
      if (g_fbmem == MAP_FAILED)
        {
          printf("ERROR: mmap framebuffer failed: %d\n", errno);
          close(g_fbfd);
          g_fbfd = -1;
          return -errno;
        }
    }

  return OK;
}

/****************************************************************************
 * Name: fb_update
 *
 * Description:
 *   Notify the framebuffer driver that the content changed (for LCD
 *   drivers that need an explicit flush).
 *
 ****************************************************************************/

static void fb_update(void)
{
#ifdef FBIO_UPDATE
  struct fb_area_s area;
  area.x = 0;
  area.y = 0;
  area.w = g_vinfo.xres;
  area.h = g_vinfo.yres;
  ioctl(g_fbfd, FBIO_UPDATE, (uintptr_t)&area);
#endif
}

/****************************************************************************
 * Name: yuyv_to_fb
 *
 * Description:
 *   Convert a YUYV 4:2:2 frame to the framebuffer's RGB565 format and
 *   blit it centered on the screen.
 *
 ****************************************************************************/

static void yuyv_to_fb(FAR const uint8_t *yuyv, uint32_t len)
{
  uint32_t fbw = g_vinfo.xres;
  uint32_t fbh = g_vinfo.yres;
  uint32_t cpw = TEST_WIDTH < fbw ? TEST_WIDTH : fbw;
  uint32_t cph = TEST_HEIGHT < fbh ? TEST_HEIGHT : fbh;
  uint32_t xoff = (fbw - cpw) / 2;
  uint32_t yoff = (fbh - cph) / 2;
  uint32_t x;
  uint32_t y;

  /* Each YUYV macro-pixel (4 bytes) encodes two pixels: Y0 U Y1 V */

  for (y = 0; y < cph; y++)
    {
      FAR const uint8_t *src = yuyv + y * TEST_WIDTH * 2;
      FAR uint16_t *dst = (FAR uint16_t *)
        (g_fbmem + (yoff + y) * g_pinfo.stride + xoff * 2);

      if ((size_t)(src - yuyv) >= len)
        {
          break;  /* Frame shorter than expected; stop early */
        }

      for (x = 0; x + 1 < cpw; x += 2)
        {
          int y0 = src[0];
          int u  = src[1] - 128;
          int y1 = src[2];
          int v  = src[3] - 128;
          int r;
          int g;
          int b;

          /* YUV -> RGB (BT.601) */

          r = y0 + ((179 * v) >> 7);
          g = y0 - ((44 * u) >> 7) - ((91 * v) >> 7);
          b = y0 + ((227 * u) >> 7);
          dst[x] = ((clamp8(r) & 0xf8) << 8) |
                   ((clamp8(g) & 0xfc) << 3) |
                   (clamp8(b) >> 3);

          r = y1 + ((179 * v) >> 7);
          g = y1 - ((44 * u) >> 7) - ((91 * v) >> 7);
          b = y1 + ((227 * u) >> 7);
          dst[x + 1] = ((clamp8(r) & 0xf8) << 8) |
                       ((clamp8(g) & 0xfc) << 3) |
                       (clamp8(b) >> 3);

          src += 4;
        }
    }

  fb_update();
}

