  /* Split into per-micro-frame transactions.
   * Each micro-frame carries up to mult * maxpacket bytes (the Multi
   * field in bpl[2] tells the HC how many transactions per micro-frame).
   */

  {
    size_t   remaining   = buflen;
    uint32_t off         = (uint32_t)(bufphys & 0xfff);
    uint32_t per_uframe  = (uint32_t)epinfo->maxpacket * epinfo->mult;
    int      uf;

    for (uf = 0; uf < 8 && remaining > 0; uf++)
      {
        uint32_t chunk    = remaining > (size_t)per_uframe ?
                            per_uframe : (uint32_t)remaining;
        uint32_t pg       = off >> 12;
        uint32_t page_off = off & 0xfff;
        uint32_t flags;

        flags = (page_off & ITD_TRAN_XOFFS_MASK) |
                ((pg << ITD_TRAN_PG_SHIFT) & ITD_TRAN_PG_MASK) |
                (chunk << ITD_TRAN_LENGTH_SHIFT) |
                ITD_TRAN_STATUS_ACTIVE;

        if (remaining - chunk == 0 || uf == 7)
          {
            flags |= ITD_TRAN_IOC;
          }

        itd->hw.trans[uf] = sunxi_swap32(flags);

        off       += chunk;
        remaining -= chunk;
      }

    for (; uf < 8; uf++)
      {
        itd->hw.trans[uf] = 0;
      }
  }
}

