/****************************************************************************
 * Name: sunxi_itd_fill
 *
 * Description:
 *   Fill one iTD's hardware fields (buffer page list + per-micro-frame
 *   transactions) for an isochronous IN transfer of up to maxpacket bytes
 *   from the given buffer.
 *
 ****************************************************************************/

static void sunxi_itd_fill(struct sunxi_itd_s *itd,
                           struct sunxi_epinfo_s *epinfo,
                           uint8_t *buffer, size_t buflen)
{
  uintptr_t bufphys;

  itd->epinfo = epinfo;
  itd->buffer = buffer;
  itd->buflen = buflen;
  itd->result = -EBUSY;

  up_flush_dcache((uintptr_t)buffer, (uintptr_t)buffer + buflen);
  bufphys = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);

  /* bpl[0]: devaddr + endpoint + page 0 base */

  itd->hw.bpl[0] = sunxi_swap32(
    ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
    ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
    (bufphys & ITD_BUFPTR_MASK));

  /* bpl[1]: maxpkt + direction + page 1 base */

  itd->hw.bpl[1] = sunxi_swap32(
    ((uint32_t)epinfo->maxpacket << ITD_BUFPTR1_MAXPKT_SHIFT) |
    (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
    ((bufphys + 0x1000) & ITD_BUFPTR_MASK));

  /* bpl[2]: multi (transactions per micro-frame) + page 2 base */

  {
    uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
                         (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
                                               ITD_BUFPTR2_MULTI_1;
    itd->hw.bpl[2] = sunxi_swap32(multi_val |
                                  ((bufphys + 0x2000) & ITD_BUFPTR_MASK));
  }

  /* bpl[3..6]: pages 3-6 */
  itd->hw.bpl[3] = sunxi_swap32((bufphys + 0x3000) & ITD_BUFPTR_MASK);
  itd->hw.bpl[4] = sunxi_swap32((bufphys + 0x4000) & ITD_BUFPTR_MASK);
  itd->hw.bpl[5] = sunxi_swap32((bufphys + 0x5000) & ITD_BUFPTR_MASK);
  itd->hw.bpl[6] = sunxi_swap32((bufphys + 0x6000) & ITD_BUFPTR_MASK);

  /* Program a SINGLE isochronous transaction (one micro-frame) in slot 0.
   *
   * One micro-frame == one UVC payload: for high-bandwidth endpoints the
   * Multi field (bpl[2]) tells the controller to issue up to `mult` back-
   * to-back packets within this one micro-frame, but the payload header
   * appears only once, at offset 0.  The data lands contiguously, so the
   * UVC layer can parse exactly one header at the start of the buffer.
   *
   * We deliberately do NOT spread the buffer across all 8 micro-frames:
   * that would concatenate 8 independent USB packets (each with its own
   * payload header) and destroy the per-payload framing the UVC parser
   * relies on.
   */

  {
    uint32_t off      = (uint32_t)(bufphys & 0xfff);
    uint32_t pg       = off >> 12;
    uint32_t page_off = off & 0xfff;
    uint32_t flags;
    int      uf;

    flags = (page_off & ITD_TRAN_XOFFS_MASK) |
            ((pg << ITD_TRAN_PG_SHIFT) & ITD_TRAN_PG_MASK) |
            ((uint32_t)buflen << ITD_TRAN_LENGTH_SHIFT) |
            ITD_TRAN_STATUS_ACTIVE |
            ITD_TRAN_IOC;

    itd->hw.trans[0] = sunxi_swap32(flags);

    for (uf = 1; uf < 8; uf++)
      {
        itd->hw.trans[uf] = 0;
      }
  }
}

static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
                            struct sunxi_epinfo_s *epinfo,
                            uint8_t *buffer, size_t buflen)
{
  (void)rhport;

  /* Payload framing: limit each transfer to a SINGLE isochronous micro-
   * frame (up to mult * maxpacket bytes).  This preserves USB packet
   * boundaries up to the caller, so the UVC layer sees exactly one payload
   * per DRVR_TRANSFER and can parse the per-payload header at offset 0.
   * Packing 8 micro-frames into one iTD concatenated 8 packets and
   * destroyed the payload-header boundaries.
   */

  {
    size_t per_uframe = (size_t)epinfo->maxpacket * epinfo->mult;
    if (buflen > per_uframe)
      {
        buflen = per_uframe;
      }
  }

  if (buflen == 0)
    {
      return -EINVAL;
    }

  /* Plan-B: allocate one iTD, fill it, and install it into ISOC_FRAME_SLOTS
   * evenly spaced periodic frame-list slots so the controller services it
   * many times per traversal.  Controller stays running (no stop/start).
   */

  {
    struct sunxi_itd_s *itd = sunxi_itd_alloc();
    uint32_t itd_link;
    int slot;

    if (itd == NULL)
      {
        return -ENOMEM;
      }

    sunxi_itd_fill(itd, epinfo, buffer, buflen);

    /* Preserve the existing periodic chain (interrupt QH) after the iTD. */

    itd->hw.nlp = g_framelist[0];  /* already correct byte order */
    up_clean_dcache((uintptr_t)&itd->hw,
                    (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
    UP_DSB();

    itd_link = sunxi_swap32(sunxi_physramaddr((uintptr_t)&itd->hw)) |
               PFL_TYP_ITD;
    for (slot = 0; slot < FRAME_LIST_SIZE; slot += ISOC_FRAME_STRIDE)
      {
        g_framelist[slot] = itd_link;
      }

    up_clean_dcache((uintptr_t)&g_framelist[0],
                    (uintptr_t)&g_framelist[0] +
                    FRAME_LIST_SIZE * sizeof(uint32_t));
    UP_DSB();

    g_active_itd = itd;
  }

  return OK;
}

