      itd->hw.bpl[2] = sunxi_swap32(multi_val |
                                    ((pgbase + 0x2000) & ITD_BUFPTR_MASK));
    }

    itd->hw.bpl[3] = sunxi_swap32((pgbase + 0x3000) & ITD_BUFPTR_MASK);
    itd->hw.bpl[4] = sunxi_swap32((pgbase + 0x4000) & ITD_BUFPTR_MASK);
    itd->hw.bpl[5] = sunxi_swap32((pgbase + 0x5000) & ITD_BUFPTR_MASK);
    itd->hw.bpl[6] = sunxi_swap32((pgbase + 0x6000) & ITD_BUFPTR_MASK);
  }

  /* Program all 8 transactions: transaction i reads one payload into
   * buffer + i*maxpacket.  The offset relative to the page-aligned base
   * carries both the page-select (bits 12-14) and X-offset (bits 0-11).
   */

  for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
    {
      uint32_t off = (uint32_t)((bufphys & 0xfff) + (uint32_t)uf * maxpkt);
      uint32_t pg       = off >> 12;
      uint32_t page_off = off & 0xfff;
      uint32_t flags;

      flags = (page_off & ITD_TRAN_XOFFS_MASK) |
              ((pg << ITD_TRAN_PG_SHIFT) & ITD_TRAN_PG_MASK) |
              (maxpkt << ITD_TRAN_LENGTH_SHIFT) |
              ITD_TRAN_STATUS_ACTIVE;

      /* Interrupt on the last transaction of the iTD. */

      if (uf == ISOC_ITD_UFRAMES - 1)
        {
          flags |= ITD_TRAN_IOC;
        }

      itd->hw.trans[uf] = sunxi_swap32(flags);
    }

  /* Preserve the periodic (interrupt) chain after this iTD. */

  itd->hw.nlp = g_isoc.nlp;

  up_clean_dcache((uintptr_t)&itd->hw,
                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
  UP_DSB();
}

/****************************************************************************
 * Name: sunxi_isoc_setup
 *
 * Description:
 *   Ensure the isochronous IN ring is running for this endpoint, then record
 *   the caller's buffer for the current DRVR_TRANSFER.  The ring itself is
 *   installed once (idempotent): a set of ISOC_ITD_UFRAMES-wide iTDs mapped
 *   across the whole periodic frame list so the controller collects payloads
 *   continuously.  Each DRVR_TRANSFER returns exactly one payload, drained
 *   from the ring in sunxi_ioc_wait().
 *
 ****************************************************************************/

static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
                            struct sunxi_epinfo_s *epinfo,
                            uint8_t *buffer, size_t buflen)
{
  (void)rhport;

  if (buffer == NULL || buflen == 0)
    {
      return -EINVAL;
    }

  /* If the ring is already running for this endpoint, just latch the caller
   * buffer for this transfer and return; the pipeline keeps filling.
   */

  if (g_isoc.epinfo == epinfo && g_isoc.buf != NULL)
    {
      g_isoc.user_buf    = buffer;
      g_isoc.user_buflen = buflen;
      return OK;
    }

  /* First transfer on this endpoint: build and install the ring. */

  if (g_isoc.buf == NULL)
    {
      g_isoc.buf = kmm_memalign(4096,
                     (size_t)CONFIG_SUNXI_EHCI_NITDS * ISOC_ITD_BUFSZ);
      if (g_isoc.buf == NULL)
        {
          return -ENOMEM;
        }
    }

  g_isoc.epinfo      = epinfo;
  g_isoc.user_buf    = buffer;
  g_isoc.user_buflen = buflen;
  g_isoc.maxpacket   = epinfo->maxpacket;
  g_isoc.head        = 0;
  g_isoc.drain_pl    = 0;
  g_isoc.pl_n        = 0;
  g_isoc.armed       = false;
  g_isoc.nlp         = g_framelist[0];  /* periodic-QH link (already swapped) */

  /* Arm every ring iTD and map it across the periodic frame list:
   * frame-list slot j -> itd[j % NITDS].
   */

  {
    int i;
    int slot;

    for (i = 0; i < CONFIG_SUNXI_EHCI_NITDS; i++)
      {
        sunxi_itd_arm(i);
      }

    for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
      {
        int idx = slot % CONFIG_SUNXI_EHCI_NITDS;
        uint32_t link =
          sunxi_swap32(sunxi_physramaddr((uintptr_t)&g_itdpool[idx].hw)) |
          PFL_TYP_ITD;
        g_framelist[slot] = link;
      }

    up_clean_dcache((uintptr_t)&g_framelist[0],
                    (uintptr_t)&g_framelist[0] +
                    FRAME_LIST_SIZE * sizeof(uint32_t));
    UP_DSB();
  }

  return OK;
}

/****************************************************************************
 * Name: sunxi_isoc_teardown
 *
 * Description:
 *   Detach the ring from the periodic frame list, restoring every slot to
 *   the interrupt QH link, and mark the ring inactive.  Called on endpoint
 *   cancel/free.  The DMA buffer is retained for reuse.
 *
 ****************************************************************************/

static void sunxi_isoc_teardown(void)
{
  int slot;

  if (g_isoc.epinfo == NULL)
    {
      return;
    }

  for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
    {
      g_framelist[slot] = g_isoc.nlp;
    }
  up_clean_dcache((uintptr_t)&g_framelist[0],
                  (uintptr_t)&g_framelist[0] +
                  FRAME_LIST_SIZE * sizeof(uint32_t));
  UP_DSB();

  g_isoc.epinfo   = NULL;
  g_isoc.user_buf = NULL;
  g_isoc.pl_n     = 0;
  g_isoc.drain_pl = 0;
  g_isoc.armed    = false;
}

