#ifndef CONFIG_USBHOST_ISOC_DISABLE
      /* Isochronous IN: drain exactly one payload from the ring pipeline.
       * The ring keeps collecting payloads continuously; each DRVR_TRANSFER
       * (i.e. each call here) returns the next non-empty payload, copied out
       * of the ring's DMA buffer into the caller's buffer.
       */

      if (g_isoc.epinfo == epinfo && g_isoc.buf != NULL)
        {
          int spins = 0;

          for (; ; )
            {
              struct sunxi_itd_s *itd = &g_itdpool[g_isoc.head];
              int uf;

              /* (1) Return the next buffered, non-empty payload (if any). */

              while (g_isoc.pl_n > 0 && g_isoc.drain_pl < g_isoc.pl_n)
                {
                  uint32_t pi  = g_isoc.drain_pl++;
                  uint32_t len = g_isoc.pl_len[pi];
                  uint8_t *src;
                  size_t   n;

                  if (len == 0)
                    {
                      continue;  /* Empty micro-frame; skip it */
                    }

                  src = itd->buffer + g_isoc.pl_off[pi];
                  n   = len > g_isoc.user_buflen ? g_isoc.user_buflen : len;
                  memcpy(g_isoc.user_buf, src, n);

                  epinfo->xfrd    = n;
                  epinfo->result  = OK;
                  epinfo->iocwait = false;
                  return epinfo->result;
                }

              /* (2) Head iTD fully drained: re-arm it (so the controller
               * refills it on its next pass) and advance to the next iTD.
               */

              if (g_isoc.pl_n > 0)
                {
                  sunxi_itd_arm(g_isoc.head);
                  g_isoc.head     = (g_isoc.head + 1) %
                                    CONFIG_SUNXI_EHCI_NITDS;
                  g_isoc.pl_n     = 0;
                  g_isoc.drain_pl = 0;
                  itd = &g_itdpool[g_isoc.head];
                }

              /* (3) Parse the head iTD once the controller has finished it. */

              up_invalidate_dcache((uintptr_t)&itd->hw,
                (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

              {
                bool still_active = false;

                for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
                  {
                    uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
                    if (tran & ITD_TRAN_STATUS_ACTIVE)
                      {
                        still_active = true;
                        break;
                      }
                  }

                if (!still_active)
                  {
                    /* Completed: invalidate the data region, then record each
                     * micro-frame's actual received length.
                     */

                    up_invalidate_dcache((uintptr_t)itd->buffer,
                      (uintptr_t)itd->buffer +
                      (size_t)ISOC_ITD_UFRAMES * g_isoc.maxpacket);

                    for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
                      {
                        uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
                        uint32_t rem  = (tran & ITD_TRAN_LENGTH_MASK) >>
                                        ITD_TRAN_LENGTH_SHIFT;
                        bool err = (tran & (ITD_TRAN_STATUS_XACTERR |
                                            ITD_TRAN_STATUS_BABBLE |
                                            ITD_TRAN_STATUS_DBERROR)) != 0;

                        g_isoc.pl_off[uf] = (uint32_t)uf * g_isoc.maxpacket;
                        g_isoc.pl_len[uf] = err ? 0 : rem;
                      }

                    g_isoc.pl_n     = ISOC_ITD_UFRAMES;
                    g_isoc.drain_pl = 0;
                    continue;  /* Back to (1) to return a payload */
                  }
              }

              /* (4) Head iTD not ready yet.  Bail out if the transfer was
               * canceled/disconnected underneath us, otherwise poll at
               * micro-frame granularity.
               */

              if (!epinfo->iocwait)
                {
                  return epinfo->result;
                }

              up_udelay(125);            /* 1 micro-frame */
              if (++spins > 4000)        /* ~0.5s watchdog */
                {
                  epinfo->xfrd    = 0;
                  epinfo->result  = -EAGAIN;
                  epinfo->iocwait = false;
                  return epinfo->result;
                }
            }
        }
      else
#endif
        {
          ret = nxsem_wait_uninterruptible(&epinfo->iocsem);
        }

