 * are left inactive (only reachable if mult>1 makes 8*per_uf exceed the
 * per-iTD buffer; our uncompressed mult==1 stream never hits this).
 */

for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
  {
    uint32_t slot_off = (uint32_t)uf * per_uf;
    uint32_t off      = (uint32_t)(bufphys & 0xfff) + slot_off;
    uint32_t pg       = off >> 12;
    uint32_t page_off = off & 0xfff;
    uint32_t flags;

    if (slot_off + per_uf > ISOC_ITD_BUFSZ)
      {
        itd->hw.trans[uf] = 0;  /* No room; leave inactive */
        continue;
      }

    flags = (page_off & ITD_TRAN_XOFFS_MASK) |
            ((pg << ITD_TRAN_PG_SHIFT) & ITD_TRAN_PG_MASK) |
            (per_uf << ITD_TRAN_LENGTH_SHIFT) |
            ITD_TRAN_STATUS_ACTIVE;

    /* Interrupt on the last transaction of the iTD. */

    if (uf == ISOC_ITD_UFRAMES - 1)
      {
        flags |= ITD_TRAN_IOC;
      }

    itd->hw.trans[uf] = sunxi_swap32(flags);
  }

