{
  int spins = 0;
  uint32_t per_uf = (uint32_t)g_isoc.maxpacket *
    (g_isoc.epinfo->mult ? g_isoc.epinfo->mult : 1);

  for (; ; )
    {
      int scan;

      /* (1) Harvest: scan the ring for iTDs the controller has
       * finished; copy each non-empty payload into the software FIFO
       * and IMMEDIATELY re-arm the iTD so it stays available to the
       * controller.  This keeps all N iTDs armed at all times, so the
       * controller never runs out of write targets and never drops a
       * packet.  Scan starts at ring_head (the oldest un-harvested
       * iTD) and follows completion order (0,1,..,N-1,0,..).
       */

      for (scan = 0; scan < CONFIG_SUNXI_EHCI_NITDS; scan++)
        {
          int idx = (g_isoc.ring_head + scan) % CONFIG_SUNXI_EHCI_NITDS;
          struct sunxi_itd_s *itd = &g_itdpool[idx];
          bool active = false;
          int uf;

          up_invalidate_dcache((uintptr_t)&itd->hw,
            (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

          for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
            {
              if (sunxi_swap32(itd->hw.trans[uf]) &
                  ITD_TRAN_STATUS_ACTIVE)
                {
                  active = true;
                  break;
                }
            }

          if (active)
            {
              break;  /* Oldest not done yet; stop, preserve order */
            }

          /* Completed: stage its payloads, then re-arm immediately. */

          up_invalidate_dcache((uintptr_t)itd->buffer,
            (uintptr_t)itd->buffer +
            (size_t)ISOC_ITD_UFRAMES * per_uf);

          for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
            {
              uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
              uint32_t rem  = (tran & ITD_TRAN_LENGTH_MASK) >>
                              ITD_TRAN_LENGTH_SHIFT;
              bool err = (tran & (ITD_TRAN_STATUS_XACTERR |
                                  ITD_TRAN_STATUS_BABBLE |
                                  ITD_TRAN_STATUS_DBERROR)) != 0;

              if (err || rem == 0)
                {
                  continue;
                }

              if (g_isoc.s_cnt < ISOC_STAGE_SLOTS)
                {
                  uint32_t n = rem > ISOC_STAGE_SLOTSZ ?
                               ISOC_STAGE_SLOTSZ : rem;
                  memcpy(g_isoc.stage +
                           (size_t)g_isoc.s_tail * ISOC_STAGE_SLOTSZ,
                         itd->buffer + (uint32_t)uf * per_uf, n);
                  g_isoc.slen[g_isoc.s_tail] = (uint16_t)n;
                  g_isoc.s_tail =
                    (g_isoc.s_tail + 1) % ISOC_STAGE_SLOTS;
                  g_isoc.s_cnt++;
                }
              /* else FIFO full: consumer is behind; drop (rare). */
            }

          sunxi_itd_arm(idx);
          g_isoc.ring_head =
            (g_isoc.ring_head + 1) % CONFIG_SUNXI_EHCI_NITDS;
        }

      /* (2) Serve one payload from the FIFO, if any. */

      if (g_isoc.s_cnt > 0)
        {
          uint32_t len = g_isoc.slen[g_isoc.s_head];
          uint8_t *src = g_isoc.stage +
                         (size_t)g_isoc.s_head * ISOC_STAGE_SLOTSZ;
          size_t   n   = len > g_isoc.user_buflen ?
                         g_isoc.user_buflen : len;

          memcpy(g_isoc.user_buf, src, n);
          g_isoc.s_head = (g_isoc.s_head + 1) % ISOC_STAGE_SLOTS;
          g_isoc.s_cnt--;

          epinfo->xfrd    = n;
          epinfo->result  = OK;
          epinfo->iocwait = false;
          return epinfo->result;
        }

      /* (3) Nothing staged yet.  Bail out if canceled, else poll at
       * micro-frame granularity.
       */

      if (!epinfo->iocwait)
        {
          return epinfo->result;
        }

      up_udelay(125);            /* 1 micro-frame */
      if (++spins > 4000)        /* ~0.5s watchdog */
        {
          epinfo->xfrd    = 0;
          epinfo->result  = -EAGAIN;
          epinfo->iocwait = false;
          return epinfo->result;
        }

