/* DIAG + fix: an uncompressed YUYV frame is EXACTLY WxHx2 bytes.  A
 * frame that arrives short or long is misaligned and, rendered as-is,
 * shifts every subsequent row -> the diagonal "stripe" artifact.  Only
 * render exactly-sized frames; count the size distribution so we can
 * see how often the assembler produces a clean frame.
 */

{
  static uint32_t n_exact;
  static uint32_t n_short;
  static uint32_t n_long;
  const uint32_t exact = TEST_WIDTH * TEST_HEIGHT * 2;

  if (buf.bytesused == exact)      n_exact++;
  else if (buf.bytesused < exact)  n_short++;
  else                             n_long++;

  if (buf.bytesused == exact)
    {
      yuyv_to_fb((const uint8_t *)buf.m.userptr, buf.bytesused);
      frames++;
