/* Deliver frame to video subsystem.
 *
 * For a fixed-size (uncompressed) format, always deliver exactly
 * max_frame_size bytes so the consumer sees whole, row-aligned frames.
 * A frame that assembled short is zero-padded to size; a frame that
 * assembled long is truncated.  This keeps every delivered frame the
 * exact expected length even when payload jitter makes the raw
 * assembled length wobble by a few rows (which otherwise shifts all
 * following rows and shows up as diagonal "stripes").
 */

if (priv->capture_cb != NULL && priv->user_buf != NULL)
  {
    size_t want = priv->max_frame_size;
    size_t copy_len;

    if (want == 0 || want > priv->user_buflen)
      {
        want = priv->user_buflen;
      }

    copy_len = MIN(priv->frame_offset, want);
    memcpy(priv->user_buf, priv->frame_buf, copy_len);

    /* Zero-pad the remainder so the frame is exactly `want` bytes. */

    if (copy_len < want)
      {
        memset(priv->user_buf + copy_len, 0, want - copy_len);
      }

    /* Call the capture completion callback with the fixed frame size. */

    priv->capture_cb(0, want, 0, priv->capture_arg);
  }

priv->frame_offset = 0;

