{
  /* Reset on FID change (the TRUE frame boundary) and count how many EOF
   * flags and how many data bytes fall inside one FID run.  A healthy
   * uncompressed frame = 1 FID run, exactly 1 EOF, ~153600 bytes.  Multiple
   * EOFs per FID run (or bytes != 153600) pinpoints the assembler fault.
   */

  static uint8_t  cur_fid = 0xff;
  static uint32_t data_pls;
  static uint32_t empty_pls;
  static uint32_t bytes;
  static uint32_t eofs;
  static int      fcnt;

  bool eof = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;

  if (fid != cur_fid && cur_fid != 0xff)
    {
      /* End of a FID run: report it. */

      if ((fcnt++ % 30) == 0)
        {
          syslog(LOG_ERR,
            "FIDRUN: data=%u empty=%u bytes=%u eofs=%u\n",
            data_pls, empty_pls, bytes, eofs);
        }

      data_pls = empty_pls = bytes = eofs = 0;
    }

  cur_fid = fid;

  if (data_len > 0) { data_pls++; bytes += data_len; }
  else              { empty_pls++; }
  if (eof)            { eofs++; }
}

