  /* Measure the EOF-to-EOF span: total data bytes and FID flips between two
   * consecutive EOF flags.  This is the span my EOF-only assembler treats
   * as one frame.  If bytes != 153600 here, the camera's EOF does not
   * delimit a full uncompressed frame and we need a different delimiter.
   */

  static uint32_t span_bytes;
  static uint32_t span_fidflips;
  static uint8_t  span_fid = 0xff;
  static int      scnt;

  bool eof = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;

  if (span_fid != 0xff && fid != span_fid)
    {
      span_fidflips++;
    }

  span_fid = fid;
  span_bytes += data_len;

  if (eof)
    {
      if ((scnt++ % 30) == 0)
        {
          syslog(LOG_ERR, "SPAN(eof2eof): bytes=%u fidflips=%u\n",
                 span_bytes, span_fidflips);
        }

      span_bytes = 0;
      span_fidflips = 0;
    }
}

