/* Phase the consumer to the controller.
 *
 * All frame-list slots map slot j -> itd[j % NITDS], so the controller
 * completes iTDs in the strict repeating order 0,1,..,N-1,0,..  The
 * consumer harvests starting from ring_head in the SAME order.  If ring_head
 * does not match where the controller actually is, the consumer waits for an
 * iTD the controller filled long ago (already lapped/overwritten) while the
 * freshly-filled ones get re-armed unread -> payloads arrive out of order
 * (observed as FID flipping ~7x/frame and torn frames on some runs).
 *
 * Read FRINDEX (bits 3-13 = current frame number) and start the consumer a
 * few iTDs BEHIND the controller's current slot, so ring_head points at an
 * iTD the controller has just finished and will not revisit for ~N frames.
 */

{
  int i;
  int slot;
  uint32_t frindex = sunxi_getreg(&HCOR->frindex);
  uint32_t frame   = (frindex >> 3) & 0x3ff;   /* current frame number */

  /* Start 2 iTDs behind the controller's current position (mod N). */

  g_isoc.ring_head = (uint8_t)(((frame + CONFIG_SUNXI_EHCI_NITDS) - 2) %
                               CONFIG_SUNXI_EHCI_NITDS);

  for (i = 0; i < CONFIG_SUNXI_EHCI_NITDS; i++)
    {
      sunxi_itd_arm(i);
    }

