static void sunxi_itd_arm(int idx)
{
  struct sunxi_itd_s    *itd    = &g_itdpool[idx];
  struct sunxi_epinfo_s *epinfo = g_isoc.epinfo;
  uint8_t   *buffer = g_isoc.buf + (size_t)idx * ISOC_ITD_BUFSZ;
  uintptr_t  bufphys;
  uint32_t   maxpkt = g_isoc.maxpacket;

  /* Bytes per micro-frame: for high-bandwidth endpoints the controller may
   * issue up to `mult` packets per micro-frame back-to-back, so one payload
   * slot spans mult*maxpacket bytes.  For mult==1 this is just maxpacket.
   */

  uint32_t   per_uf = maxpkt * (epinfo->mult ? epinfo->mult : 1);
  int        uf;

  itd->epinfo = epinfo;
  itd->buffer = buffer;
  itd->buflen = ISOC_ITD_BUFSZ;
  itd->result = -EBUSY;

  bufphys = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);

  /* Buffer Page Pointer List (bpl[0..6]) spans 7 physical 4K pages starting
   * at the (page-aligned) base of this iTD's buffer.  ISOC_ITD_BUFSZ (8K)
   * needs at most 3 pages, but program all 7 defensively.  The per-page base
   * must be page-aligned; the per-transaction XOFFS supplies the low 12 bits.
   */

  {
    uintptr_t pgbase = bufphys & ITD_BUFPTR_MASK;

    itd->hw.bpl[0] = sunxi_swap32(
      ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
      ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
      (pgbase & ITD_BUFPTR_MASK));

    itd->hw.bpl[1] = sunxi_swap32(
      ((uint32_t)maxpkt << ITD_BUFPTR1_MAXPKT_SHIFT) |
      (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
      ((pgbase + 0x1000) & ITD_BUFPTR_MASK));

    {
      uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
                           (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
                                                 ITD_BUFPTR2_MULTI_1;
      itd->hw.bpl[2] = sunxi_swap32(multi_val |
                                    ((pgbase + 0x2000) & ITD_BUFPTR_MASK));
    }

    itd->hw.bpl[3] = sunxi_swap32((pgbase + 0x3000) & ITD_BUFPTR_MASK);
    itd->hw.bpl[4] = sunxi_swap32((pgbase + 0x4000) & ITD_BUFPTR_MASK);
    itd->hw.bpl[5] = sunxi_swap32((pgbase + 0x5000) & ITD_BUFPTR_MASK);
    itd->hw.bpl[6] = sunxi_swap32((pgbase + 0x6000) & ITD_BUFPTR_MASK);
  }

