   * per_uf bytes) into buffer + i*per_uf.  The offset relative to the
   * page-aligned base carries both the page-select (bits 12-14) and the
   * X-offset (bits 0-11).  Payloads that would run past this iTD's buffer
   * are left inactive (only reachable if mult>1 makes 8*per_uf exceed the
   * per-iTD buffer; our uncompressed mult==1 stream never hits this).
   */

  for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
    {
      uint32_t slot_off = (uint32_t)uf * per_uf;
      uint32_t off      = (uint32_t)(bufphys & 0xfff) + slot_off;
      uint32_t pg       = off >> 12;
