static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
                            struct sunxi_epinfo_s *epinfo,
                            uint8_t *buffer, size_t buflen)
{
  (void)rhport;

  if (buffer == NULL || buflen == 0)
    {
