static void sunxi_isoc_teardown(void)
{
  if (g_chain.epinfo == NULL)
    {
      return;
    }

  /* Restore the frame-list slot that held the chain head to the interrupt
   * QH link.  The chain's nlp links are stale but harmless — the controller
   * follows the frame-list slot, not the old chain.
   */

  /* NOTE: we don't know which slot the chain was installed at (it advances
   * per frame), so restore all slots.  This is safe because only ISOC slots
   * were modified.
   */

  {
    int slot;

    for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
      {
        g_framelist[slot] = g_chain.nlp;
      }

    up_clean_dcache((uintptr_t)&g_framelist[0],
                    (uintptr_t)&g_framelist[0] +
                    FRAME_LIST_SIZE * sizeof(uint32_t));
    UP_DSB();
  }

  g_chain.epinfo   = NULL;
  g_chain.user_buf = NULL;
  g_chain.f_cnt    = 0;
}

