/****************************************************************************
 * Name: sunxi_chain_build
 *
 * Description:
 *   Build a chain of ISOC_SLOTS_PER_FRAME iTDs from the pool and install
 *   it into the periodic frame list starting at start_slot.
 *
 *   Each iTD is filled with ISOC_ITD_UFRAMES transactions (one payload per
 *   micro-frame).  iTDs are linked via nlp; the last iTD's nlp points to
 *   the interrupt QH (g_chain.nlp) so the periodic schedule continues.
 *
 *   After this call the controller will process all iTDs in the chain in
 *   order.  Each iTD's IOC (on last transaction) wakes the consumer.
 *
 *   Caller must hold g_ehci.lock.
 *
 ****************************************************************************/

static void sunxi_chain_build(uint32_t start_slot)
{
  int n = ISOC_SLOTS_PER_FRAME;
  int i;
  uint32_t qh_link = g_chain.nlp;  /* interrupt QH (already swapped) */

  /* If we don't have enough iTDs in the pool, use fewer. */

  if (n > ISOC_ITD_POOL)
    {
      n = ISOC_ITD_POOL;
    }

  g_chain.n_itds   = (uint8_t)n;
  g_chain.poll_idx = 0;
  g_chain.f_head   = 0;
  g_chain.f_tail   = 0;
  g_chain.f_cnt    = 0;

  /* Arm each iTD.  The last iTD's nlp points to the interrupt QH; all
   * others point to the next iTD in the chain.
   */

  for (i = 0; i < n; i++)
    {
      FAR uint8_t *buffer = g_chain.buf + (size_t)i * ISOC_ITD_BUFSZ;
      uint32_t next_link;

      if (i < n - 1)
        {
          /* Link to the next iTD in the chain. */

          next_link = sunxi_swap32(
            sunxi_physramaddr((uintptr_t)&g_itdpool[i + 1].hw)) |
            PFL_TYP_ITD;
        }
      else
        {
          /* Last iTD: link to the interrupt QH. */

          next_link = qh_link;
        }

      sunxi_itd_arm(i, buffer, next_link);
    }

  /* Insert the chain head into the frame list at start_slot. */

  g_framelist[start_slot] =
    sunxi_swap32(sunxi_physramaddr((uintptr_t)&g_itdpool[0].hw)) |
    PFL_TYP_ITD;

  up_clean_dcache((uintptr_t)&g_framelist[start_slot],
                  (uintptr_t)&g_framelist[start_slot] + sizeof(uint32_t));
  UP_DSB();
}

