static int sunxi_isoc_setup(struct sunxi_rhport_s *rhport,
                            struct sunxi_epinfo_s *epinfo,
                            uint8_t *buffer, size_t buflen)
{
  (void)rhport;

  if (buffer == NULL || buflen == 0)
    {
      return -EINVAL;
    }

  /* If the chain is already running for this endpoint, just latch the caller
   * buffer for this transfer and return; the pipeline keeps filling.
   */

  if (g_ring.epinfo == epinfo && g_ring.buf != NULL)
    {
      g_ring.user_buf    = buffer;
      g_ring.user_buflen = buflen;
      return OK;
    }

  /* First transfer on this endpoint: build and install the chain. */

  if (g_ring.buf == NULL)
    {
      g_ring.buf = kmm_memalign(4096,
                      (size_t)ISOC_ITD_POOL * ISOC_ITD_BUFSZ);
      if (g_ring.buf == NULL)
        {
          return -ENOMEM;
        }
    }

  if (g_ring.fifo == NULL)
    {
      g_ring.fifo = kmm_memalign(64,
                       (size_t)ISOC_FIFO_SLOTS * ISOC_FIFO_SLOTSZ);
      if (g_ring.fifo == NULL)
        {
          return -ENOMEM;
        }
    }

  g_ring.epinfo      = epinfo;
  g_ring.user_buf    = buffer;
  g_ring.user_buflen = buflen;
  g_ring.maxpacket   = epinfo->maxpacket;
  g_ring.nlp         = g_framelist[0];  /* periodic-QH link (swapped) */

  /* Build the first chain starting at frame-list slot 0. */

  sunxi_chain_build(0);

  return OK;
}

