 * The controller processes each iTD exactly once (no modulo race).
 * When an iTD's ACTIVE bits clear, we harvest its payloads into the
 * FIFO and advance to the next iTD.  When the whole chain is consumed,
 * we recycle the iTDs and build the next chain.
 *
 * Each DRVR_TRANSFER returns exactly one payload from the FIFO.
 */

if (g_ring.epinfo == epinfo && g_ring.buf != NULL)
  {
    int spins = 0;
    uint32_t per_uf = (uint32_t)g_ring.maxpacket *
      (g_ring.epinfo->mult ? g_ring.epinfo->mult : 1);

    for (; ; )
      {
        /* (1) If we have buffered payloads, serve one immediately. */

        if (g_ring.f_cnt > 0)
          {
            uint32_t len = g_ring.fifo_len[g_ring.f_head];
            uint8_t *src = g_ring.fifo +
                           (size_t)g_ring.f_head * ISOC_FIFO_SLOTSZ;
            size_t   n   = len > g_ring.user_buflen ?
                           g_ring.user_buflen : len;

            memcpy(g_ring.user_buf, src, n);
            g_ring.f_head = (g_ring.f_head + 1) % ISOC_FIFO_SLOTS;
            g_ring.f_cnt--;

            epinfo->xfrd    = n;
            epinfo->result  = OK;
            epinfo->iocwait = false;
            return epinfo->result;
          }

        /* (2) FIFO empty — batch-harvest ALL completed iTDs from the
         * chain in one pass.  This avoids the per-iTD 1ms tickwait
         * that made the single-iTD-per-iteration approach too slow.
         * Stop at the first still-ACTIVE iTD (preserves order).
         */

        while (g_ring.poll_idx < g_ring.n_itds)
          {
            int idx = g_ring.poll_idx;
            struct sunxi_itd_s *itd = &g_itdpool[idx];
            bool active = false;
            int uf;

            up_invalidate_dcache((uintptr_t)&itd->hw,
              (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

            for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
              {
                if (sunxi_swap32(itd->hw.trans[uf]) &
                    ITD_TRAN_STATUS_ACTIVE)
                  {
                    active = true;
                    break;
                  }
              }

            if (active)
              {
                break;  /* Not ready yet; stop batch harvest */
              }

            /* iTD completed: harvest its payloads into FIFO. */

            up_invalidate_dcache((uintptr_t)itd->buffer,
              (uintptr_t)itd->buffer +
              (size_t)ISOC_ITD_UFRAMES * per_uf);

            for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
              {
                uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
                uint32_t rem  = (tran & ITD_TRAN_LENGTH_MASK) >>
                                ITD_TRAN_LENGTH_SHIFT;
                bool err = (tran & (ITD_TRAN_STATUS_XACTERR |
                                    ITD_TRAN_STATUS_BABBLE |
                                    ITD_TRAN_STATUS_DBERROR)) != 0;

                if (err || rem == 0)
                  {
                    continue;
                  }

                if (g_ring.f_cnt < ISOC_FIFO_SLOTS)
                  {
                    uint32_t n = rem > ISOC_FIFO_SLOTSZ ?
                                 ISOC_FIFO_SLOTSZ : rem;
                    memcpy(g_ring.fifo +
                             (size_t)g_ring.f_tail *
                             ISOC_FIFO_SLOTSZ,
                           itd->buffer + (uint32_t)uf * per_uf, n);
                    g_ring.fifo_len[g_ring.f_tail] =
                      (uint16_t)n;
                    g_ring.f_tail =
                      (g_ring.f_tail + 1) % ISOC_FIFO_SLOTS;
                    g_ring.f_cnt++;
                  }
              }

            g_ring.poll_idx++;
          }

        /* If entire chain consumed, build next chain at a fresh
         * frame-list slot so the controller never revisits an iTD
         * we haven't drained yet.
         */

        if (g_ring.poll_idx >= g_ring.n_itds)
          {
            uint32_t next_slot =
              (g_ring.start_slot +
               (uint32_t)g_ring.n_itds) %
              (uint32_t)FRAME_LIST_SIZE;
            sunxi_chain_build(next_slot);
