/* The harvest scan above found no completed iTDs.  Instead of
 * blocking for a full 1ms tick (which limits throughput to
 * ~2300 payload/sec), do a brief micro-frame delay then
 * immediately loop back to harvest again.  The IOC interrupt
 * also posts the semaphore, so if the delay isn't enough the
 * semaphore wakes us.
 *
 * 125µs = one micro-frame.  8 such delays = 1ms = one iTD
 * completion.  With N=32 iTDs, the controller fills one iTD
 * per 1ms, so we only need to wait ~1ms before the next one
 * is ready.
 */

up_udelay(125);

if (++spins > 8000)        /* ~1s watchdog */
  {
    epinfo->xfrd    = 0;
    epinfo->result  = -EAGAIN;
    epinfo->iocwait = false;
    return epinfo->result;
  }

