  /* Frame delimiting + integrity gating.
   *
   * Known issue: the EHCI isochronous ring occasionally delivers payloads
   * slightly out of order (a hardware-timing race in the periodic schedule),
   * which shows up as the FID bit "flipping" several times within a single
   * real frame and a frame whose assembled size != max_frame_size.  Rendering
   * such a frame produces the diagonal "stripe" artifact.
   *
   * Clean frames (exactly one FID value across the frame, and exactly
   * max_frame_size bytes) DO arrive interleaved with the corrupted ones.  So
   * we assemble by EOF but GATE delivery: only hand a frame to the video
   * subsystem when it is intact (fidflips <= 1 and size == max_frame_size).
   * Corrupted frames are dropped (the previous good frame stays on screen /
   * is simply not recorded), trading some frame-rate for a clean image.
   */

  /* Track FID flips within the current frame being assembled. */

  if (priv->asm_lastfid != 0xff && fid != priv->asm_lastfid)
    {
      priv->asm_fidflips++;
    }

  priv->asm_lastfid = fid;

  /* Append data to frame buffer */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* Deliver on EOF, or as a fallback when we've accumulated a whole frame's
   * worth of data without seeing EOF (a missed/dropped EOF would otherwise
   * merge two frames).  max_frame_size is the exact uncompressed frame size.
   */

  if ((header->bmHeaderInfo & UVC_HEADER_EOF) ||
      (priv->max_frame_size > 0 &&
       priv->frame_offset >= priv->max_frame_size))
    {
      /* Integrity check by SIZE.  FID flips are NOT a corruption signal for
       * this camera (observed: a clean 153600 frame has 13 flips).  Size
       * alone separates good frames from torn ones.  Accept frames within
       * [max_frame_size, max_frame_size+4KB]; the copy truncates to max.
       */

      bool clean = (priv->max_frame_size == 0) ||
                   (priv->frame_offset >= priv->max_frame_size &&
                    priv->frame_offset <= priv->max_frame_size + 4096);

      /* DIAG (throttled): assembled size + flips + accept/drop. */

      {
        static int eofcnt;
        if ((eofcnt++ % 30) == 0)
          {
            syslog(LOG_ERR, "EOF: frame=%zu flips=%u %s\n",
                   priv->frame_offset, priv->asm_fidflips,
                   clean ? "OK" : "DROP");
          }
      }

      /* Deliver only intact frames. */

      if (clean && priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = MIN(priv->frame_offset, priv->user_buflen);
          memcpy(priv->user_buf, priv->frame_buf, copy_len);

          /* Call the capture completion callback */

          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      /* Reset assembly state for the next frame (whether kept or dropped). */

      priv->frame_offset = 0;
      priv->asm_fidflips = 0;
      priv->asm_lastfid  = 0xff;
    }
}

