  /* Frame delimiting — FID toggle ONLY.
   *
   * Diagnostic data shows this camera's EOF flag fires at unpredictable
   * byte positions (22K, 59K, 128K, ...), NOT at the true frame boundary
   * (153600).  Between EOFs, fidflips=0 — the FID bit is stable.  This
   * proves FID, not EOF, marks the true frame boundary.
   *
   * Therefore: accumulate all data (ignoring EOF entirely) and deliver
   * when the FID bit toggles (meaning a new frame's first payload arrived,
   * so the PREVIOUS frame is complete).  Also deliver when we accumulate
   * exactly max_frame_size bytes (the uncompressed frame size) as a safety
   * net for missed FID toggles.
   */

  if (priv->asm_lastfid != 0xff && fid != priv->asm_lastfid)
    {
      /* FID changed: the previous frame is complete.  Deliver it. */

      if (priv->frame_offset > 0 &&
          priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = MIN(priv->frame_offset, priv->user_buflen);
          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }

  priv->asm_lastfid = fid;

  /* Append data to frame buffer */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* Safety: if we've accumulated a full frame's worth of data without a
   * FID toggle, deliver anyway to prevent merging two frames.
   */

  if (priv->max_frame_size > 0 &&
      priv->frame_offset >= priv->max_frame_size)
    {
      if (priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->max_frame_size;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }

  /* DIAG (throttled): log EOF events with current frame_offset for
   * understanding the camera's EOF timing (informational only, EOF
   * does NOT trigger delivery).
   */

  if (header->bmHeaderInfo & UVC_HEADER_EOF)
    {
      static int eofcnt;
      if ((eofcnt++ % 60) == 0)
        {
          syslog(LOG_ERR, "EOF at offset=%zu (FID-delimited, not used)\n",
                 priv->frame_offset);
        }
    }
}

