   *     toggle once per frame).
   *
   * The only reliable delimiter is the expected frame size itself.  For
   * uncompressed YUYV 320×240, every frame is exactly 153600 bytes.
   * Accumulate data continuously; when frame_offset hits max_frame_size,
   * deliver the frame and reset.  Ignore EOF and FID entirely for
   * delimiting (FID is tracked only as a DIAG counter).
   */

  UNUSED(fid);

  /* Append data to frame buffer */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* Deliver when we've accumulated exactly one frame's worth of data. */

  if (priv->max_frame_size > 0 &&
      priv->frame_offset >= priv->max_frame_size)
    {
      if (priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->max_frame_size;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }
}

