/* Deliver when we've accumulated ≥95% of a frame (reference threshold).
 * Always deliver EXACTLY max_frame_size bytes so the consumer always
 * receives a fixed-size, row-aligned frame.  Short data is zero-padded;
 * excess is truncated.  This prevents the consumer from seeing variable-
 * size frames (which causes rows to shift and produce stripes).
 */

if (priv->max_frame_size > 0 &&
    priv->frame_offset >= (priv->max_frame_size * 95 / 100))
  {
    if (priv->capture_cb != NULL && priv->user_buf != NULL)
      {
        size_t want = priv->max_frame_size;
        size_t copy_len;

        if (want > priv->user_buflen)
          {
            want = priv->user_buflen;
          }

        copy_len = priv->frame_offset < want ? priv->frame_offset : want;
        memcpy(priv->user_buf, priv->frame_buf, copy_len);

        /* Zero-pad the remainder so the frame is always exactly `want`
         * bytes, keeping all rows aligned.
         */

        if (copy_len < want)
          {
            memset(priv->user_buf + copy_len, 0, want - copy_len);
          }

        priv->capture_cb(0, want, 0, priv->capture_arg);
      }

    priv->frame_offset = 0;
  }

