  /* Frame delimiting — dual EOF + FID with size gate (Linux UVC style).
   *
   * This camera toggles FID 11-35 times per frame and fires EOF at
   * unpredictable byte positions.  The strategy:
   *
   *  1. FID toggle → deliver current frame (if ≥95% of expected size),
   *     then reset.  This is the primary delimiter: each FID value
   *     represents a distinct time window of camera data.
   *
   *  2. EOF → also deliver (if ≥95%), then reset.  This catches frames
   *     where FID didn't toggle at the boundary.
   *
   *  3. Size gate: ≥95% of max_frame_size (Linux reference threshold).
   *     Frames below this are dropped (partial/too short).
   *
   *  4. Max-size safety: if frame_offset reaches max_frame_size, deliver
   *     immediately to prevent merging two frames.
   */

  /* (a) FID toggle: new frame boundary */

  if (priv->asm_lastfid != 0xff && fid != priv->asm_lastfid)
    {
      /* Deliver the previous frame if it meets the size threshold. */

      if (priv->frame_offset >= (priv->max_frame_size * 95 / 100) &&
          priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->frame_offset;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }

  priv->asm_lastfid = fid;

  /* (b) Append data to frame buffer */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* (c) EOF: deliver the frame if ≥95%, then reset. */

  if (header->bmHeaderInfo & UVC_HEADER_EOF)
    {
      if (priv->frame_offset >= (priv->max_frame_size * 95 / 100) &&
          priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->frame_offset;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }

  /* (d) Max-size safety: deliver if we've reached the expected size. */

  if (priv->max_frame_size > 0 &&
      priv->frame_offset >= priv->max_frame_size)
    {
      if (priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->max_frame_size;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }
}

